/* feed/g-L7.js: the words of 368 cards — GENERATED by tools/build-feed.mjs from the corpus. Never edit by hand; rerun it. */
export const BODY = {"level-7":{"id":"level-7","kind":"level","level":7,"src":"level:7","title":"Level 7 · Letters and Ratios","body":"Multiplying and dividing negatives, kinds of number, ratio, percentage change and speed, first letters for numbers, circles and volume, chance as a fraction, and factorials and arrangements.","route":"#/atlas","cta":"See the road"},"land-l7-negatives":{"id":"land-l7-negatives","kind":"land","level":7,"src":"land:l7-negatives","title":"Signs that multiply — in The Deep Mine","body":"4 stops on this stretch of the road: A day of ups and downs · Multiplying negatives · Dividing negatives · Squares and brackets.","art":"art/w-mine.webp","route":"#/world/mine","cta":"Visit Mine"},"land-l7-factors":{"id":"land-l7-factors","kind":"land","level":7,"src":"land:l7-factors","title":"Kinds of number — in The Prime Quarry","body":"4 stops on this stretch of the road: Square, triangle, cube or prime · Building with prime stones · How far to test a prime · Cubes and cube roots.","art":"art/w-quarry.webp","route":"#/world/quarry","cta":"Visit Quarry"},"land-l7-decimals":{"id":"land-l7-decimals","kind":"land","level":7,"src":"land:l7-decimals","title":"Percentages, ratio and rates — in The Decimal Dock","body":"6 stops on this stretch of the road: Percentages of an amount · Find one, then scale · Sales and rises · Ratio: simplify and share · Speed, distance and time · Simple interest.","art":"art/w-dock.webp","route":"#/world/dock","cta":"Visit Dock"},"land-l7-algebra":{"id":"land-l7-algebra","kind":"land","level":7,"src":"land:l7-algebra","title":"Letters for numbers — in Set Island","body":"4 stops on this stretch of the road: Working backwards · Letters for numbers · Collecting like terms · Solving equations on a balance.","art":"art/w-setisland.webp","route":"#/world/setisland","cta":"Visit Set Island"},"land-l7-shape":{"id":"land-l7-shape","kind":"land","level":7,"src":"land:l7-shape","title":"Circles, triangles and solids — in Shape City","body":"3 stops on this stretch of the road: Round the circle · Building a triangle from three sides · Volume and surface area.","art":"art/w-shapecity.webp","route":"#/world/shapecity","cta":"Visit Shape City"},"land-l7-data":{"id":"land-l7-data","kind":"land","level":7,"src":"land:l7-data","title":"Chance and arrangements — in The Data Carnival","body":"4 stops on this stretch of the road: Chance as a fraction · Counting all the ways · Factorials · Putting things in order.","art":"art/w-carnival.webp","route":"#/world/carnival","cta":"Visit Carnival"},"trick-volume-cuboid-idea":{"id":"trick-volume-cuboid-idea","kind":"trick","src":"stop:volume-cuboid#idea","title":"Volume and surface area","body":"Volume = length × width × height: one layer of cubes, times the number of layers. Surface area adds the six faces, which come in three matching pairs. Fill the bottom of the box with 1 cm cubes. They make a rectangle, so the bottom layer holds length × width cubes — 5 × 3 = 15. Every layer above is the same, and there are as many layers as the box is tall: 15 × 4 = 60 cm³.","cta":"Learn the trick","level":7,"route":"#/stop/volume-cuboid"},"story-volume-cuboid-open":{"id":"story-volume-cuboid-open","kind":"story","src":"story:volume-cuboid#open","badge":{"id":"story","label":"A story"},"title":"Packing the crate","body":"At the harbour, Suki and Kwame pack cube-shaped tins into a crate 5 tins long, 3 wide and 4 tall. — with Suki and Kwame.","art":"art/s-harbour.webp","cta":"Read the story","level":7,"route":"#/stop/volume-cuboid"},"hook-volume-cuboid-hook":{"id":"hook-volume-cuboid-hook","kind":"hook","src":"stop:volume-cuboid#hook","title":"Can you? — Volume and surface area","body":"A box is 5 cm long, 3 cm wide and 4 cm tall. How many 1 cm cubes fill it?","cta":"Find out how","level":7,"route":"#/stop/volume-cuboid"},"idea-volume-cuboid-case0":{"id":"idea-volume-cuboid-case0","kind":"idea","src":"stop:volume-cuboid#case0","title":"Volume and surface area: Volume","body":"Count the cubes in the bottom layer, then multiply by the number of layers. The answer is in cm³.","cta":"See it worked","level":7,"route":"#/stop/volume-cuboid"},"worked-volume-cuboid-worked0":{"id":"worked-volume-cuboid-worked0","kind":"worked","src":"stop:volume-cuboid#worked0","title":"Worked out — Volume and surface area: Volume","body":"A box is 5 cm long, 3 cm wide and 4 cm tall. What is its volume, in cm³?: Cubes in the bottom layer: 5 × 3 → 15 · Number of layers → 4 · 15 × 4 → 60","cta":"Watch it step by step","level":7,"route":"#/stop/volume-cuboid"},"idea-volume-cuboid-case1":{"id":"idea-volume-cuboid-case1","kind":"idea","src":"stop:volume-cuboid#case1","title":"Volume and surface area: Surface area","body":"Now you want the wrapping, not the filling: three different faces, each appearing twice. The answer is in cm².","cta":"See it worked","level":7,"route":"#/stop/volume-cuboid"},"worked-volume-cuboid-worked1":{"id":"worked-volume-cuboid-worked1","kind":"worked","src":"stop:volume-cuboid#worked1","title":"Worked out — Volume and surface area: Surface area","body":"A box is 5 cm long, 3 cm wide and 4 cm tall. What is its total surface area, in cm²?: Front and back: 2 × 5 × 4 → 40 · Top and bottom: 2 × 5 × 3 → 30 · The two ends: 2 × 3 × 4 → 24 · Add the six faces → 94","cta":"Watch it step by step","level":7,"route":"#/stop/volume-cuboid"},"why-volume-cuboid-why1":{"id":"why-volume-cuboid-why1","kind":"why","src":"stop:volume-cuboid#why1","title":"Why “Volume and surface area” works","body":"Surface area is the wrapping paper, not the filling. A box has six flat faces, and opposite faces are the same size: front and back, top and bottom, left and right. So you find three areas and double each one.","cta":"See why","level":7,"route":"#/stop/volume-cuboid"},"why-volume-cuboid-why2":{"id":"why-volume-cuboid-why2","kind":"why","src":"stop:volume-cuboid#why2","title":"Why “Volume and surface area” works","body":"Volume counts cubes (cm³, three lengths multiplied) and surface area counts squares (cm², two lengths multiplied). That is why a box can hold a lot but need little paper, or the other way round.","cta":"See why","level":7,"route":"#/stop/volume-cuboid"},"algebra-volume-cuboid-alg":{"id":"algebra-volume-cuboid-alg","kind":"algebra","src":"stop:volume-cuboid#alg","title":"The algebra behind “Volume and surface area”","body":"V = l × w × h · SA = 2(lw + lh + wh)","cta":"See why","level":7,"route":"#/stop/volume-cuboid"},"moment-volume-cuboid-beat3":{"id":"moment-volume-cuboid-beat3","kind":"moment","src":"story:volume-cuboid#beat3","badge":{"id":"story","label":"A story"},"title":"Packing the crate — on the notepad","body":"Kwame: Four layers of fifteen. 15 × 4 = 60","cta":"Read the story","level":7,"route":"#/stop/volume-cuboid"},"moral-volume-cuboid-beat5":{"id":"moral-volume-cuboid-beat5","kind":"moral","src":"story:volume-cuboid#beat5","badge":{"id":"story","label":"A story"},"title":"Kwame, in “Packing the crate”","body":"Sixty tins fill it. Length times width times height.","cta":"Read the story","level":7,"route":"#/stop/volume-cuboid"},"try-volume-cuboid-L7":{"id":"try-volume-cuboid-L7","kind":"try","level":7,"src":"try:volume-cuboid@7/1#0","title":"Volume and surface area — your turn","route":"#/stop/volume-cuboid","cta":"Practise this stop","play":{"q":"A box is 4 cm long, 5 cm wide and 4 cm tall. What is its volume, in cm³?","opts":["80","20","4"],"after":"Volume = length × width × height: one layer of cubes, times the number of layers. Surface area adds the six faces, which come in three matching pairs."}},"trick-interest-simple-idea":{"id":"trick-interest-simple-idea","kind":"trick","src":"stop:interest-simple#idea","title":"Simple interest","body":"Work out one year's interest — the rate per cent of the amount you put in — then multiply by the years. Interest is what a bank pays you for letting it use your money. This story's bank pays 5% a year: for every 100 coins you leave with it, it pays 5 coins each year. So 200 coins earns 5% of 200 = 10 coins a year.","cta":"Learn the trick","level":7,"route":"#/stop/interest-simple"},"story-interest-simple-open":{"id":"story-interest-simple-open","kind":"story","src":"story:interest-simple#open","badge":{"id":"story","label":"A story"},"title":"The story bank","body":"In the city, the bank in this story pays 5% a year. Suki puts in 200 coins for 3 years. — with Ines and Suki.","art":"art/s-city.webp","cta":"Read the story","level":7,"route":"#/stop/interest-simple"},"idea-interest-simple-case0":{"id":"idea-interest-simple-case0","kind":"idea","src":"stop:interest-simple#case0","title":"Simple interest: The interest","body":"One year's interest is the same every year, because it is always worked out on what was first put in. Multiply by the years.","cta":"See it worked","level":7,"route":"#/stop/interest-simple"},"why-interest-simple-why1":{"id":"why-interest-simple-why1","kind":"why","src":"stop:interest-simple#why1","title":"Why “Simple interest” works","body":"With simple interest the interest is always worked out on the amount you first put in, so every year is the same helping: 10, 10 and 10. Three years is 3 × 10 = 30 coins, and the account ends with 230.","cta":"See why","level":7,"route":"#/stop/interest-simple"},"algebra-interest-simple-alg":{"id":"algebra-interest-simple-alg","kind":"algebra","src":"stop:interest-simple#alg","title":"The algebra behind “Simple interest”","body":"I = P × r × t ÷ 100","cta":"See why","level":7,"route":"#/stop/interest-simple"},"moral-interest-simple-beat5":{"id":"moral-interest-simple-beat5","kind":"moral","src":"story:interest-simple#beat5","badge":{"id":"story","label":"A story"},"title":"Suki, in “The story bank”","body":"30 coins of interest. Simple.","cta":"Read the story","level":7,"route":"#/stop/interest-simple"},"trick-round-the-circle-idea":{"id":"trick-round-the-circle-idea","kind":"trick","src":"stop:round-the-circle#idea","title":"Round the circle","body":"The diameter is two radii. The distance round (the circumference) is about 3.14 × the diameter. The radius goes from the centre to the edge. The diameter goes right across through the centre, so it is one radius out and another radius back: two radii.","cta":"Learn the trick","level":7,"route":"#/stop/round-the-circle"},"story-round-the-circle-open":{"id":"story-round-the-circle-open","kind":"story","src":"story:round-the-circle#open","badge":{"id":"story","label":"A story"},"title":"The rolling wheel","body":"Dax and Vesper wheel a bike through the city. Its wheel is 60 cm across. — with Vesper and Dax.","art":"art/s-city.webp","cta":"Read the story","level":7,"route":"#/stop/round-the-circle"},"idea-round-the-circle-case0":{"id":"idea-round-the-circle-case0","kind":"idea","src":"stop:round-the-circle#case0","title":"Round the circle: Radius to diameter","body":"The diameter goes right across through the centre: one radius out and one radius back, so double it.","cta":"See it worked","level":7,"route":"#/stop/round-the-circle"},"idea-round-the-circle-case1":{"id":"idea-round-the-circle-case1","kind":"idea","src":"stop:round-the-circle#case1","title":"Round the circle: Diameter to radius","body":"Going the other way, the radius is only halfway across — so halve the diameter.","cta":"See it worked","level":7,"route":"#/stop/round-the-circle"},"idea-round-the-circle-case2":{"id":"idea-round-the-circle-case2","kind":"idea","src":"stop:round-the-circle#case2","title":"Round the circle: Round, from the diameter","body":"The distance round is a little more than 3 diameters: 3.14 × the diameter. Do the 3 × first, then add the small 0.14 ×.","cta":"See it worked","level":7,"route":"#/stop/round-the-circle"},"idea-round-the-circle-case3":{"id":"idea-round-the-circle-case3","kind":"idea","src":"stop:round-the-circle#case3","title":"Round the circle: Round, from the radius","body":"π works with the diameter, so double the radius FIRST. Multiplying the radius by 3.14 gives only half the way round.","cta":"See it worked","level":7,"route":"#/stop/round-the-circle"},"why-round-the-circle-why1":{"id":"why-round-the-circle-why1","kind":"why","src":"stop:round-the-circle#why1","title":"Why “Round the circle” works","body":"Every circle is a scaled-up or scaled-down copy of every other circle. So the distance round divided by the distance across is the same number for all of them. That number is called pi (π), and it is a little more than 3.14.","cta":"See why","level":7,"route":"#/stop/round-the-circle"},"algebra-round-the-circle-alg":{"id":"algebra-round-the-circle-alg","kind":"algebra","src":"stop:round-the-circle#alg","title":"The algebra behind “Round the circle”","body":"d = 2r · C = π × d ≈ 3.14 × d","cta":"See why","level":7,"route":"#/stop/round-the-circle"},"moral-round-the-circle-beat5":{"id":"moral-round-the-circle-beat5","kind":"moral","src":"story:round-the-circle#beat5","badge":{"id":"story","label":"A story"},"title":"Dax, in “The rolling wheel”","body":"188.4 cm every turn — nearly two metres!","cta":"Read the story","level":7,"route":"#/stop/round-the-circle"},"try-round-the-circle-L7":{"id":"try-round-the-circle-L7","kind":"try","level":7,"src":"try:round-the-circle@7/1#0","title":"Round the circle — your turn","route":"#/stop/round-the-circle","cta":"Practise this stop","play":{"q":"A circle has a radius of 10 cm. What is its diameter, in cm?","opts":["20","10","21"],"after":"The diameter is two radii. The distance round (the circumference) is about 3.14 × the diameter."}},"trick-construct-triangle-idea":{"id":"trick-construct-triangle-idea","kind":"trick","src":"stop:construct-triangle#idea","title":"Building a triangle from three sides","body":"Draw the longest side, then swing an arc from each end for the other two: a triangle is only possible if the two shorter sides add up to MORE than the longest. Draw the longest side as the base, from A to B. The third corner must be 3 cm from A, and every point 3 cm from A lies on a circle round A — so open the compasses to 3 cm and swing an arc from A. Do the same from B with 4 cm. The third corner is wherever the two arcs cross.","cta":"Learn the trick","level":7,"route":"#/stop/construct-triangle"},"story-construct-triangle-open":{"id":"story-construct-triangle-open","kind":"story","src":"story:construct-triangle#open","badge":{"id":"story","label":"A story"},"title":"Three straws","body":"Pip has three straws, 3 cm, 4 cm and 7 cm long, and wants a triangle. Mira gets out a ruler and compasses. — with Mira and Pip.","art":"art/s-room.webp","cta":"Read the story","level":7,"route":"#/stop/construct-triangle"},"hook-construct-triangle-hook":{"id":"hook-construct-triangle-hook","kind":"hook","src":"stop:construct-triangle#hook","title":"Can you? — Building a triangle from three sides","body":"Three sticks: 3 cm, 4 cm and 7 cm. Can they make a triangle? Build it with a ruler and compasses before you guess.","cta":"Find out how","level":7,"route":"#/stop/construct-triangle"},"idea-construct-triangle-case0":{"id":"idea-construct-triangle-case0","kind":"idea","src":"stop:construct-triangle#case0","title":"Building a triangle from three sides: The arcs cross","body":"The two shorter sides together reach further than the base, so the arcs cross above it and the third corner is there.","cta":"See it worked","level":7,"route":"#/stop/construct-triangle"},"worked-construct-triangle-worked0":{"id":"worked-construct-triangle-worked0","kind":"worked","src":"stop:construct-triangle#worked0","title":"Worked out — Building a triangle from three sides: The arcs cross","body":"Can a triangle be built with sides of 5 cm, 6 cm and 8 cm?: The longest side — draw it as the base → 8 · Add the other two sides → 11 · The arcs cross only if that is MORE than 8. Can the triangle be built? → Yes","cta":"Watch it step by step","level":7,"route":"#/stop/construct-triangle"},"idea-construct-triangle-case1":{"id":"idea-construct-triangle-case1","kind":"idea","src":"stop:construct-triangle#case1","title":"Building a triangle from three sides: The arcs never meet","body":"The two shorter sides together do not even reach across the base, so the arcs stop short of each other.","cta":"See it worked","level":7,"route":"#/stop/construct-triangle"},"idea-construct-triangle-case2":{"id":"idea-construct-triangle-case2","kind":"idea","src":"stop:construct-triangle#case2","title":"Building a triangle from three sides: The arcs only touch","body":"The trap: the shorter sides add up to EXACTLY the base. The arcs meet on the base line, the triangle lies flat — so the answer is still no.","cta":"See it worked","level":7,"route":"#/stop/construct-triangle"},"worked-construct-triangle-worked2":{"id":"worked-construct-triangle-worked2","kind":"worked","src":"stop:construct-triangle#worked2","title":"Worked out — Building a triangle from three sides: The arcs only touch","body":"Can a triangle be built with sides of 3 cm, 4 cm and 7 cm?: The longest side — draw it as the base → 7 · Add the other two sides → 7 · The arcs cross only if that is MORE than 7. Can the triangle be built? → No","cta":"Watch it step by step","level":7,"route":"#/stop/construct-triangle"},"idea-construct-triangle-case3":{"id":"idea-construct-triangle-case3","kind":"idea","src":"stop:construct-triangle#case3","title":"Building a triangle from three sides: Longest third side","body":"The third side must be shorter than the other two laid end to end — so one less than their sum, as a whole number.","cta":"See it worked","level":7,"route":"#/stop/construct-triangle"},"worked-construct-triangle-worked3":{"id":"worked-construct-triangle-worked3","kind":"worked","src":"stop:construct-triangle#worked3","title":"Worked out — Building a triangle from three sides: Longest third side","body":"Two sides of a triangle are 5 cm and 8 cm. The third side is a whole number of cm. What is the longest it can be, in cm?: The two sides end to end: 5 + 8 → 13 · The third side must be shorter than that. The longest whole number it can be → 12","cta":"Watch it step by step","level":7,"route":"#/stop/construct-triangle"},"idea-construct-triangle-case4":{"id":"idea-construct-triangle-case4","kind":"idea","src":"stop:construct-triangle#case4","title":"Building a triangle from three sides: Shortest third side","body":"The short side and the third side must reach past the long one — so the third side must be MORE than the difference.","cta":"See it worked","level":7,"route":"#/stop/construct-triangle"},"worked-construct-triangle-worked4":{"id":"worked-construct-triangle-worked4","kind":"worked","src":"stop:construct-triangle#worked4","title":"Worked out — Building a triangle from three sides: Shortest third side","body":"Two sides of a triangle are 5 cm and 8 cm. The third side is a whole number of cm. What is the shortest it can be, in cm?: The gap the short side cannot close: 8 − 5 → 3 · The third side must be longer than that. The shortest whole number it can be → 4","cta":"Watch it step by step","level":7,"route":"#/stop/construct-triangle"},"why-construct-triangle-why1":{"id":"why-construct-triangle-why1","kind":"why","src":"stop:construct-triangle#why1","title":"Why “Building a triangle from three sides” works","body":"The arcs can only cross if the two shorter sides, laid end to end, reach further than the base. If they add up to less, the arcs never meet. If they add up to exactly the base — 3 + 4 = 7 — the arcs only touch, on the base line itself: the \"triangle\" lies flat and has no third corner. So the two shorter sides must add up to more than the longest one.","cta":"See why","level":7,"route":"#/stop/construct-triangle"},"why-construct-triangle-why2":{"id":"why-construct-triangle-why2","kind":"why","src":"stop:construct-triangle#why2","title":"Why “Building a triangle from three sides” works","body":"When the arcs do cross, the triangle is fixed: any triangle with those three sides fits exactly on top of yours. That is why a frame of three rods is rigid when four rods wobble. It also tells you what a missing third side can be: longer than the difference of the other two, shorter than their sum, and never exactly either.","cta":"See why","level":7,"route":"#/stop/construct-triangle"},"algebra-construct-triangle-alg":{"id":"algebra-construct-triangle-alg","kind":"algebra","src":"stop:construct-triangle#alg","title":"The algebra behind “Building a triangle from three sides”","body":"sides a ≤ b ≤ c make a triangle only if a + b > c · third side x: (b − a) < x < (a + b)","cta":"See why","level":7,"route":"#/stop/construct-triangle"},"moment-construct-triangle-beat5":{"id":"moment-construct-triangle-beat5","kind":"moment","src":"story:construct-triangle#beat5","badge":{"id":"story","label":"A story"},"title":"Three straws — on the notepad","body":"Pip: So if the long one were a bit shorter, the arcs would cross above the base? 7 − 1 = 6","cta":"Read the story","level":7,"route":"#/stop/construct-triangle"},"moral-construct-triangle-beat6":{"id":"moral-construct-triangle-beat6","kind":"moral","src":"story:construct-triangle#beat6","badge":{"id":"story","label":"A story"},"title":"Mira, in “Three straws”","body":"Yes. The two shorter sides must add up to MORE than the longest. 3 + 4 is not more than 7, so no triangle.","cta":"Read the story","level":7,"route":"#/stop/construct-triangle"},"try-construct-triangle-L7":{"id":"try-construct-triangle-L7","kind":"try","level":7,"src":"try:construct-triangle@7/1#0","title":"Building a triangle from three sides — your turn","route":"#/stop/construct-triangle","cta":"Practise this stop","play":{"q":"Can a triangle be built with sides of 10 cm, 3 cm and 7 cm?","opts":["No","Yes"],"after":"Draw the longest side, then swing an arc from each end for the other two: a triangle is only possible if the two shorter sides add up to MORE than the longest."}},"trick-ups-and-downs-idea":{"id":"trick-ups-and-downs-idea","kind":"trick","src":"stop:ups-and-downs#idea","title":"A day of ups and downs","body":"Add up all the ups, add up all the downs, and then do one sum at the end. A long string of pluses and minuses is a lift log: each number is a trip, up or down. You could ride every trip in turn, crossing ground level again and again. But the order of the trips does not change where the lift ends up — up 8 then down 9 lands in the same place as down 9 then up 8.","cta":"Learn the trick","level":7,"route":"#/stop/ups-and-downs"},"story-ups-and-downs-open":{"id":"story-ups-and-downs-open","kind":"story","src":"story:ups-and-downs#open","badge":{"id":"story","label":"A story"},"title":"The fair game","body":"At the fair, Rafi’s game scores go: −5, then +8, −9, +3 and −6. — with Theo and Rafi.","art":"art/s-fair.webp","cta":"Read the story","level":7,"route":"#/stop/ups-and-downs"},"hook-ups-and-downs-hook":{"id":"hook-ups-and-downs-hook","kind":"hook","src":"stop:ups-and-downs#hook","title":"Can you? — A day of ups and downs","body":"−5 + 8 − 9 + 3 − 6. Do you have to ride every trip one by one?","cta":"Find out how","level":7,"route":"#/stop/ups-and-downs"},"worked-ups-and-downs-worked0":{"id":"worked-ups-and-downs-worked0","kind":"worked","src":"stop:ups-and-downs#worked0","title":"Worked out — A day of ups and downs","body":"−5 + 8 − 9 + 3 − 6: All the ups: 8 + 3 → 11 · All the downs: 5 + 9 + 6 → 20 · Up 11 and down 20: where do you finish? → -9","cta":"Watch it step by step","level":7,"route":"#/stop/ups-and-downs"},"why-ups-and-downs-why1":{"id":"why-ups-and-downs-why1","kind":"why","src":"stop:ups-and-downs#why1","title":"Why “A day of ups and downs” works","body":"So sort them. Put every up trip together and every down trip together. In −5 + 8 − 9 + 3 − 6 the ups are 8 and 3, which make 11. The downs are 5, 9 and 6, which make 20.","cta":"See why","level":7,"route":"#/stop/ups-and-downs"},"why-ups-and-downs-why2":{"id":"why-ups-and-downs-why2","kind":"why","src":"stop:ups-and-downs#why2","title":"Why “A day of ups and downs” works","body":"Now there is only one sum left: up 11 and down 20. The downs win by 9, so the lift finishes 9 below ground, at −9. Two easy additions and one take-away, instead of five trips across zero.","cta":"See why","level":7,"route":"#/stop/ups-and-downs"},"algebra-ups-and-downs-alg":{"id":"algebra-ups-and-downs-alg","kind":"algebra","src":"stop:ups-and-downs#alg","title":"The algebra behind “A day of ups and downs”","body":"a₁ + a₂ + … = (sum of the positives) − (sum of the sizes of the negatives)","cta":"See why","level":7,"route":"#/stop/ups-and-downs"},"moment-ups-and-downs-beat3":{"id":"moment-ups-and-downs-beat3","kind":"moment","src":"story:ups-and-downs#beat3","badge":{"id":"story","label":"A story"},"title":"The fair game — on the notepad","body":"Rafi: And all the downs together. 5 + 9 + 6 = 20","cta":"Read the story","level":7,"route":"#/stop/ups-and-downs"},"moral-ups-and-downs-beat5":{"id":"moral-ups-and-downs-beat5","kind":"moral","src":"story:ups-and-downs#beat5","badge":{"id":"story","label":"A story"},"title":"Rafi, in “The fair game”","body":"My score is −9. Two additions and one take-away.","cta":"Read the story","level":7,"route":"#/stop/ups-and-downs"},"try-ups-and-downs-L7":{"id":"try-ups-and-downs-L7","kind":"try","level":7,"src":"try:ups-and-downs@7/1#0","title":"A day of ups and downs — your turn","route":"#/stop/ups-and-downs","cta":"Practise this stop","play":{"q":"2 − 4 + 3 = ?","opts":["1","5","4"],"after":"Add up all the ups, add up all the downs, and then do one sum at the end."}},"trick-multiply-signs-idea":{"id":"trick-multiply-signs-idea","kind":"trick","src":"stop:multiply-signs#idea","title":"Multiplying negatives","body":"Multiply the sizes, then count the minus signs: an even number of them makes the answer positive, an odd number makes it negative. Start with a positive times a negative: 3 × (−4) is three bills of 4, which is a bill of 12, so −12. Three lots of going down 4 takes you 12 below ground.","cta":"Learn the trick","level":7,"route":"#/stop/multiply-signs"},"story-multiply-signs-open":{"id":"story-multiply-signs-open","kind":"story","src":"story:multiply-signs#open","badge":{"id":"story","label":"A story"},"title":"The table that kept going","body":"Mira and Kwame are doing homework in Mira’s room. The question is −4 × (−8). — with Mira and Kwame.","art":"art/s-room.webp","cta":"Read the story","level":7,"route":"#/stop/multiply-signs"},"hook-multiply-signs-hook":{"id":"hook-multiply-signs-hook","kind":"hook","src":"stop:multiply-signs#hook","title":"Can you? — Multiplying negatives","body":"−4 × (−8). Two negatives — why on earth is the answer positive?","cta":"Find out how","level":7,"route":"#/stop/multiply-signs"},"idea-multiply-signs-case0":{"id":"idea-multiply-signs-case0","kind":"idea","src":"stop:multiply-signs#case0","title":"Multiplying negatives: One negative","body":"Lots of a bill is a bigger bill: one negative number in the product makes the answer negative.","cta":"See it worked","level":7,"route":"#/stop/multiply-signs"},"worked-multiply-signs-worked0":{"id":"worked-multiply-signs-worked0","kind":"worked","src":"stop:multiply-signs#worked0","title":"Worked out — Multiplying negatives: One negative","body":"3 × (−4): Ignore the signs: 3 × 4 → 12 · How many of the numbers are negative? → 1 · Each pair of negatives makes a positive. So the answer is → -12","cta":"Watch it step by step","level":7,"route":"#/stop/multiply-signs"},"idea-multiply-signs-case1":{"id":"idea-multiply-signs-case1","kind":"idea","src":"stop:multiply-signs#case1","title":"Multiplying negatives: Two negatives","body":"The pair of negatives cancels out, so the answer is positive — the times-table pattern leaves no other choice.","cta":"See it worked","level":7,"route":"#/stop/multiply-signs"},"worked-multiply-signs-worked1":{"id":"worked-multiply-signs-worked1","kind":"worked","src":"stop:multiply-signs#worked1","title":"Worked out — Multiplying negatives: Two negatives","body":"−4 × (−8): Ignore the signs: 4 × 8 → 32 · How many of the numbers are negative? → 2 · Each pair of negatives makes a positive. So the answer is → 32","cta":"Watch it step by step","level":7,"route":"#/stop/multiply-signs"},"idea-multiply-signs-case2":{"id":"idea-multiply-signs-case2","kind":"idea","src":"stop:multiply-signs#case2","title":"Multiplying negatives: Three negatives","body":"Two of them pair up and cancel; the third is left over on its own, so the answer is negative again.","cta":"See it worked","level":7,"route":"#/stop/multiply-signs"},"worked-multiply-signs-worked2":{"id":"worked-multiply-signs-worked2","kind":"worked","src":"stop:multiply-signs#worked2","title":"Worked out — Multiplying negatives: Three negatives","body":"−2 × (−3) × (−5): Ignore the signs: 2 × 3 × 5 → 30 · How many of the numbers are negative? → 3 · Each pair of negatives makes a positive. So the answer is → -30","cta":"Watch it step by step","level":7,"route":"#/stop/multiply-signs"},"why-multiply-signs-why1":{"id":"why-multiply-signs-why1","kind":"why","src":"stop:multiply-signs#why1","title":"Why “Multiplying negatives” works","body":"Now write out the times table for −4 and walk the multiplier down the lift shaft: 2 × (−4) = −8, 1 × (−4) = −4, 0 × (−4) = 0. Each step down, the answer goes UP by 4. Carry on below ground and the pattern must hold: −1 × (−4) = 4, −2 × (−4) = 8. A negative times a negative is positive — the pattern leaves no other choice.","cta":"See why","level":7,"route":"#/stop/multiply-signs"},"why-multiply-signs-why2":{"id":"why-multiply-signs-why2","kind":"why","src":"stop:multiply-signs#why2","title":"Why “Multiplying negatives” works","body":"So for any product, multiply the sizes and then count the negatives. Each pair of negatives cancels out to a positive. Two negatives: positive. Three: negative again. The size never depends on the signs — only which side of zero you land.","cta":"See why","level":7,"route":"#/stop/multiply-signs"},"algebra-multiply-signs-alg":{"id":"algebra-multiply-signs-alg","kind":"algebra","src":"stop:multiply-signs#alg","title":"The algebra behind “Multiplying negatives”","body":"(−a) × b = −(ab) ; (−a) × (−b) = ab","cta":"See why","level":7,"route":"#/stop/multiply-signs"},"moment-multiply-signs-beat4":{"id":"moment-multiply-signs-beat4","kind":"moment","src":"story:multiply-signs#beat4","badge":{"id":"story","label":"A story"},"title":"The table that kept going — on the notepad","body":"Kwame: Keep the pattern going below zero. −1 × (−8) = 8","cta":"Read the story","level":7,"route":"#/stop/multiply-signs"},"moral-multiply-signs-beat6":{"id":"moral-multiply-signs-beat6","kind":"moral","src":"story:multiply-signs#beat6","badge":{"id":"story","label":"A story"},"title":"Kwame, in “The table that kept going”","body":"The pattern had no other choice. Negative times negative is positive.","cta":"Read the story","level":7,"route":"#/stop/multiply-signs"},"try-multiply-signs-L7":{"id":"try-multiply-signs-L7","kind":"try","level":7,"src":"try:multiply-signs@7/1#0","title":"Multiplying negatives — your turn","route":"#/stop/multiply-signs","cta":"Practise this stop","play":{"q":"−5 × 4 = ?","opts":["-20","20","1"],"after":"Multiply the sizes, then count the minus signs: an even number of them makes the answer positive, an odd number makes it negative."}},"trick-divide-signs-idea":{"id":"trick-divide-signs-idea","kind":"trick","src":"stop:divide-signs#idea","title":"Dividing negatives","body":"Divide the sizes, then use the same sign rule as multiplying: same signs positive, different signs negative. Division undoes multiplication. −42 ÷ (−6) asks: what times −6 makes −42? Try 7: 7 × (−6) = −42. So the answer is 7, a positive number, even though both numbers in the question were negative.","cta":"Learn the trick","level":7,"route":"#/stop/divide-signs"},"story-divide-signs-open":{"id":"story-divide-signs-open","kind":"story","src":"story:divide-signs#open","badge":{"id":"story","label":"A story"},"title":"The new freezer","body":"Vesper’s family has a new freezer. In 4 hours its temperature falls by 24 degrees. — with Vesper and Ines.","art":"art/s-kitchen.webp","cta":"Read the story","level":7,"route":"#/stop/divide-signs"},"hook-divide-signs-hook":{"id":"hook-divide-signs-hook","kind":"hook","src":"stop:divide-signs#hook","title":"Can you? — Dividing negatives","body":"−42 ÷ (−6). Positive or negative — and how would you know?","cta":"Find out how","level":7,"route":"#/stop/divide-signs"},"idea-divide-signs-case0":{"id":"idea-divide-signs-case0","kind":"idea","src":"stop:divide-signs#case0","title":"Dividing negatives: Negative ÷ positive","body":"A negative shared out stays negative: different signs give a negative answer.","cta":"See it worked","level":7,"route":"#/stop/divide-signs"},"worked-divide-signs-worked0":{"id":"worked-divide-signs-worked0","kind":"worked","src":"stop:divide-signs#worked0","title":"Worked out — Dividing negatives: Negative ÷ positive","body":"−42 ÷ 6: Ignore the signs: 42 ÷ 6 → 7 · The signs are different. So the answer is → -7","cta":"Watch it step by step","level":7,"route":"#/stop/divide-signs"},"idea-divide-signs-case1":{"id":"idea-divide-signs-case1","kind":"idea","src":"stop:divide-signs#case1","title":"Dividing negatives: Positive ÷ negative","body":"Different signs again, just the other way round — still a negative answer. Check: what times −6 makes 42?","cta":"See it worked","level":7,"route":"#/stop/divide-signs"},"idea-divide-signs-case2":{"id":"idea-divide-signs-case2","kind":"idea","src":"stop:divide-signs#case2","title":"Dividing negatives: Negative ÷ negative","body":"Same signs, so the answer is positive — because a positive number times −6 is what makes −42.","cta":"See it worked","level":7,"route":"#/stop/divide-signs"},"idea-divide-signs-case3":{"id":"idea-divide-signs-case3","kind":"idea","src":"stop:divide-signs#case3","title":"Dividing negatives: Positive ÷ positive","body":"Same signs, positive answer: the ordinary division you already know. The rule just agrees with it.","cta":"See it worked","level":7,"route":"#/stop/divide-signs"},"worked-divide-signs-worked3":{"id":"worked-divide-signs-worked3","kind":"worked","src":"stop:divide-signs#worked3","title":"Worked out — Dividing negatives: Positive ÷ positive","body":"42 ÷ 6: Ignore the signs: 42 ÷ 6 → 7 · The signs are the same. So the answer is → 7","cta":"Watch it step by step","level":7,"route":"#/stop/divide-signs"},"why-divide-signs-why1":{"id":"why-divide-signs-why1","kind":"why","src":"stop:divide-signs#why1","title":"Why “Dividing negatives” works","body":"That is why division follows exactly the same sign rule as multiplication — every division is a multiplication read backwards. Same signs give a positive answer; different signs give a negative one.","cta":"See why","level":7,"route":"#/stop/divide-signs"},"why-divide-signs-why2":{"id":"why-divide-signs-why2","kind":"why","src":"stop:divide-signs#why2","title":"Why “Dividing negatives” works","body":"Real life does this too. A freezer that cools by 24 degrees in 4 hours changes by −24 ÷ 4 = −6 degrees each hour: a negative change shared out stays negative. The size of the answer never depends on the signs; only the side of zero does.","cta":"See why","level":7,"route":"#/stop/divide-signs"},"algebra-divide-signs-alg":{"id":"algebra-divide-signs-alg","kind":"algebra","src":"stop:divide-signs#alg","title":"The algebra behind “Dividing negatives”","body":"(−a) ÷ b = −(a ÷ b) ; (−a) ÷ (−b) = a ÷ b","cta":"See why","level":7,"route":"#/stop/divide-signs"},"moment-divide-signs-beat4":{"id":"moment-divide-signs-beat4","kind":"moment","src":"story:divide-signs#beat4","badge":{"id":"story","label":"A story"},"title":"The new freezer — on the notepad","body":"Vesper: Check it backwards. Four hours of −6. 4 × (−6) = -24","cta":"Read the story","level":7,"route":"#/stop/divide-signs"},"moral-divide-signs-beat5":{"id":"moral-divide-signs-beat5","kind":"moral","src":"story:divide-signs#beat5","badge":{"id":"story","label":"A story"},"title":"Ines, in “The new freezer”","body":"Minus six degrees an hour. Same rule as multiplying.","cta":"Read the story","level":7,"route":"#/stop/divide-signs"},"try-divide-signs-L7":{"id":"try-divide-signs-L7","kind":"try","level":7,"src":"try:divide-signs@7/1#0","title":"Dividing negatives — your turn","route":"#/stop/divide-signs","cta":"Practise this stop","play":{"q":"15 ÷ (−5) = ?","opts":["-3","3","-2"],"after":"Divide the sizes, then use the same sign rule as multiplying: same signs positive, different signs negative."}},"trick-negative-squares-idea":{"id":"trick-negative-squares-idea","kind":"trick","src":"stop:negative-squares#idea","title":"Squares and brackets","body":"Powers come before the minus sign in front — unless brackets put the minus inside the square. (−3)² means (−3) × (−3): the bracket says square the whole thing, minus and all. Two negatives multiplied make a positive, so (−3)² = 9. Any number squared, below zero or above, is never negative.","cta":"Learn the trick","level":7,"route":"#/stop/negative-squares"},"story-negative-squares-open":{"id":"story-negative-squares-open","kind":"story","src":"story:negative-squares#open","badge":{"id":"story","label":"A story"},"title":"The calculator argument","body":"In the library, Dax types −3² into a calculator and it says −9. He is sure it is broken. — with Theo and Dax.","art":"art/s-library.webp","cta":"Read the story","level":7,"route":"#/stop/negative-squares"},"idea-negative-squares-case0":{"id":"idea-negative-squares-case0","kind":"idea","src":"stop:negative-squares#case0","title":"Squares and brackets: Square in brackets","body":"The bracket puts the minus inside the square, so it is multiplied by itself too — and two negatives make a positive.","cta":"See it worked","level":7,"route":"#/stop/negative-squares"},"idea-negative-squares-case1":{"id":"idea-negative-squares-case1","kind":"idea","src":"stop:negative-squares#case1","title":"Squares and brackets: Minus, no brackets","body":"No brackets, so the power goes first and the minus waits: square the number, then make it negative.","cta":"See it worked","level":7,"route":"#/stop/negative-squares"},"idea-negative-squares-case2":{"id":"idea-negative-squares-case2","kind":"idea","src":"stop:negative-squares#case2","title":"Squares and brackets: Square, then take away","body":"Powers come before take-away: square the bracket first, then subtract.","cta":"See it worked","level":7,"route":"#/stop/negative-squares"},"idea-negative-squares-case3":{"id":"idea-negative-squares-case3","kind":"idea","src":"stop:negative-squares#case3","title":"Squares and brackets: Times a negative","body":"Multiply before you take away. Then taking away a negative is the same as adding.","cta":"See it worked","level":7,"route":"#/stop/negative-squares"},"idea-negative-squares-case4":{"id":"idea-negative-squares-case4","kind":"idea","src":"stop:negative-squares#case4","title":"Squares and brackets: Minus square plus a product","body":"Two jobs before the add: the power (square, then the minus) and the multiplication. Only then add.","cta":"See it worked","level":7,"route":"#/stop/negative-squares"},"why-negative-squares-why1":{"id":"why-negative-squares-why1","kind":"why","src":"stop:negative-squares#why1","title":"Why “Squares and brackets” works","body":"But −3² has no brackets, and powers come before everything except brackets. So you square the 3 first, which is 9, and only then apply the minus: −3² = −9. It means “the negative of 3²”. Many calculators read it exactly this way.","cta":"See why","level":7,"route":"#/stop/negative-squares"},"algebra-negative-squares-alg":{"id":"algebra-negative-squares-alg","kind":"algebra","src":"stop:negative-squares#alg","title":"The algebra behind “Squares and brackets”","body":"(−a)² = a² ; −a² = −(a²) ; c − d × (−e) = c + de","cta":"See why","level":7,"route":"#/stop/negative-squares"},"moral-negative-squares-beat5":{"id":"moral-negative-squares-beat5","kind":"moral","src":"story:negative-squares#beat5","badge":{"id":"story","label":"A story"},"title":"Theo, in “The calculator argument”","body":"So the calculator is right. −3² is −9, and (−3)² is 9. The brackets decide.","cta":"Read the story","level":7,"route":"#/stop/negative-squares"},"try-negative-squares-L7":{"id":"try-negative-squares-L7","kind":"try","level":7,"src":"try:negative-squares@7/1#0","title":"Squares and brackets — your turn","route":"#/stop/negative-squares","cta":"Practise this stop","play":{"q":"(−8)² = ?","opts":["64","65","63"],"after":"Powers come before the minus sign in front — unless brackets put the minus inside the square."}},"trick-number-types-idea":{"id":"trick-number-types-idea","kind":"trick","src":"stop:number-types#idea","title":"Square, triangle, cube or prime","body":"Test the shapes in turn: n rows of n for a square, rows of 1, 2, 3… for a triangle, n × n × n for a cube. A number that only makes a single line is prime. Numbers have shapes. A square number of dots stands in a perfect square — 16 is 4 rows of 4. A triangular number stands in a triangle: a row of 1, then 2, then 3… so 10 is 1 + 2 + 3 + 4. A cube number stacks into a perfect cube: 27 is 3 layers of 3 × 3.","cta":"Learn the trick","level":7,"route":"#/stop/number-types"},"story-number-types-open":{"id":"story-number-types-open","kind":"story","src":"story:number-types#open","badge":{"id":"story","label":"A story"},"title":"The pebble shapes","body":"Mira has 28 smooth pebbles from the garden path. Can they make a square, a triangle or a cube? — with Mira and Pip.","art":"art/s-garden.webp","cta":"Read the story","level":7,"route":"#/stop/number-types"},"hook-number-types-hook":{"id":"hook-number-types-hook","kind":"hook","src":"stop:number-types#hook","title":"Can you? — Square, triangle, cube or prime","body":"28 pebbles — can they make a square? A triangle? A cube? Or none of them?","cta":"Find out how","level":7,"route":"#/stop/number-types"},"idea-number-types-case0":{"id":"idea-number-types-case0","kind":"idea","src":"stop:number-types#case0","title":"Square, triangle, cube or prime: Square","body":"Some number of rows with that same number in each: 25 is 5 rows of 5.","cta":"See it worked","level":7,"route":"#/stop/number-types"},"worked-number-types-worked0":{"id":"worked-number-types-worked0","kind":"worked","src":"stop:number-types#worked0","title":"Worked out — Square, triangle, cube or prime: Square","body":"25 dots — which shape can they make?: Is 25 a square — some number times itself? → Yes · So its shape is → square","cta":"Watch it step by step","level":7,"route":"#/stop/number-types"},"idea-number-types-case1":{"id":"idea-number-types-case1","kind":"idea","src":"stop:number-types#case1","title":"Square, triangle, cube or prime: Triangular","body":"Rows of 1, 2, 3… each one longer: keep adding the next number and see if you land on it exactly. 28 is 1 + 2 + … + 7.","cta":"See it worked","level":7,"route":"#/stop/number-types"},"worked-number-types-worked1":{"id":"worked-number-types-worked1","kind":"worked","src":"stop:number-types#worked1","title":"Worked out — Square, triangle, cube or prime: Triangular","body":"28 dots — which shape can they make?: Is 28 a square — some number times itself? → No · Is 28 triangular — 1 + 2 + 3 + … up to some number? → Yes · So its shape is → triangular","cta":"Watch it step by step","level":7,"route":"#/stop/number-types"},"idea-number-types-case2":{"id":"idea-number-types-case2","kind":"idea","src":"stop:number-types#case2","title":"Square, triangle, cube or prime: Cube","body":"Some number times itself, times itself again: 27 is 3 layers of 3 × 3. It is not a square, so test for a cube next.","cta":"See it worked","level":7,"route":"#/stop/number-types"},"idea-number-types-case3":{"id":"idea-number-types-case3","kind":"idea","src":"stop:number-types#case3","title":"Square, triangle, cube or prime: Prime","body":"None of the three shapes fits, and the dots will only stand in one long line — no rectangle at all.","cta":"See it worked","level":7,"route":"#/stop/number-types"},"worked-number-types-worked3":{"id":"worked-number-types-worked3","kind":"worked","src":"stop:number-types#worked3","title":"Worked out — Square, triangle, cube or prime: Prime","body":"23 dots — which shape can they make?: Is 23 a square — some number times itself? → No · Is 23 triangular — 1 + 2 + 3 + … up to some number? → No · Is 23 a cube — some number times itself, times itself again? → No · Is 23 prime — can it only stand in one straight line? → Yes · So its shape is → prime","cta":"Watch it step by step","level":7,"route":"#/stop/number-types"},"why-number-types-why1":{"id":"why-number-types-why1","kind":"why","src":"stop:number-types#why1","title":"Why “Square, triangle, cube or prime” works","body":"A prime number refuses every rectangle. 7 dots can only stand in one long line of 7 — any other number of rows leaves some over. That is exactly what \"its only factors are 1 and itself\" means.","cta":"See why","level":7,"route":"#/stop/number-types"},"why-number-types-why2":{"id":"why-number-types-why2","kind":"why","src":"stop:number-types#why2","title":"Why “Square, triangle, cube or prime” works","body":"Some numbers wear two shapes: 36 is a square AND a triangle, and 64 is a square AND a cube. The questions here only use numbers with exactly one of these four shapes, so test them in order and stop at the first one that fits.","cta":"See why","level":7,"route":"#/stop/number-types"},"algebra-number-types-alg":{"id":"algebra-number-types-alg","kind":"algebra","src":"stop:number-types#alg","title":"The algebra behind “Square, triangle, cube or prime”","body":"square n² · triangular 1 + 2 + … + n = n(n + 1) ÷ 2 · cube n³ · prime: factors only 1 and itself","cta":"See why","level":7,"route":"#/stop/number-types"},"moment-number-types-beat2":{"id":"moment-number-types-beat2","kind":"moment","src":"story:number-types#beat2","badge":{"id":"story","label":"A story"},"title":"The pebble shapes — on the notepad","body":"Mira: A cube needs 3 × 3 × 3. That’s 27 — one pebble short of 28. 3 × 3 × 3 = 27","cta":"Read the story","level":7,"route":"#/stop/number-types"},"moral-number-types-beat5":{"id":"moral-number-types-beat5","kind":"moral","src":"story:number-types#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “The pebble shapes”","body":"Every pebble used. 28 is triangular!","cta":"Read the story","level":7,"route":"#/stop/number-types"},"try-number-types-L7":{"id":"try-number-types-L7","kind":"try","level":7,"src":"try:number-types@7/2#0","title":"Square, triangle, cube or prime — your turn","route":"#/stop/number-types","cta":"Practise this stop","play":{"q":"9 dots — which shape can they make?","opts":["square","triangular","cube"],"after":"Test the shapes in turn: n rows of n for a square, rows of 1, 2, 3… for a triangle, n × n × n for a cube. A number that only makes a single line is prime."}},"hook-prime-stones-hook":{"id":"hook-prime-stones-hook","kind":"hook","src":"stop:prime-stones#hook","title":"Can you? — Building with prime stones","body":"2 × 2 × 3 × 5 — which number do these four stones build?","cta":"Find out how","level":7,"route":"#/stop/prime-stones"},"worked-prime-stones-worked0":{"id":"worked-prime-stones-worked0","kind":"worked","src":"stop:prime-stones#worked0","title":"Worked out — Building with prime stones: Build the number","body":"2 × 2 × 3 × 5 = ?: 2 × 2 → 4 · 4 × 3 → 12 · 12 × 5 → 60","cta":"Watch it step by step","level":7,"route":"#/stop/prime-stones"},"worked-prime-stones-worked1":{"id":"worked-prime-stones-worked1","kind":"worked","src":"stop:prime-stones#worked1","title":"Worked out — Building with prime stones: Find the missing stone","body":"210 = 2 × 3 × 7 × ?: Multiply the stones you have: 2 × 3 × 7 → 42 · 210 ÷ 42 → 5","cta":"Watch it step by step","level":7,"route":"#/stop/prime-stones"},"why-prime-stones-why2":{"id":"why-prime-stones-why2","kind":"why","src":"stop:prime-stones#why2","title":"Why “Building with prime stones” works","body":"The surprising part is that there is only ONE set of stones for each number. Split 60 as 6 × 10 or as 4 × 15 and you still end with two 2s, a 3 and a 5. That is why a missing stone can always be found: the stones you are shown, multiplied, leave exactly one prime to finish the number.","cta":"See why","level":7,"route":"#/stop/prime-stones"},"moment-prime-stones-beat2":{"id":"moment-prime-stones-beat2","kind":"moment","src":"story:prime-stones#beat2","badge":{"id":"story","label":"A story"},"title":"Towers of stones — on the notepad","body":"Rafi: Then 4 times 3 is 12, and 12 times 5 is 60. 4 × 3 × 5 = 60","cta":"Read the story","level":7,"route":"#/stop/prime-stones"},"try-prime-stones-L7":{"id":"try-prime-stones-L7","kind":"try","level":7,"src":"try:prime-stones@7/2#0","title":"Building with prime stones — your turn","route":"#/stop/prime-stones","cta":"Practise this stop","play":{"q":"5 × 5 × 7 = ?","opts":["175","25","176"],"after":"Multiply the prime stones together one at a time. To find a missing stone, multiply the ones you have and divide."}},"trick-sieve-root-idea":{"id":"trick-sieve-root-idea","kind":"trick","src":"stop:sieve-root#idea","title":"How far to test a prime","body":"Find the biggest whole number whose square is not more than your number. You only ever need to try the primes up to that one. If a number is NOT prime, it splits into two factors: 187 = 11 × 17. The two factors cannot both be bigger than 13, because 14 × 14 is already 196 — more than 187. So one of them is always 13 or smaller. If no prime up to 13 divides 187, nothing bigger can, and the number is prime.","cta":"Learn the trick","level":7,"route":"#/stop/sieve-root"},"story-sieve-root-open":{"id":"story-sieve-root-open","kind":"story","src":"story:sieve-root#open","badge":{"id":"story","label":"A story"},"title":"The library puzzle","body":"In the library, Theo finds a puzzle card: is 187 a prime number? — with Theo and Suki.","art":"art/s-library.webp","cta":"Read the story","level":7,"route":"#/stop/sieve-root"},"hook-sieve-root-hook":{"id":"hook-sieve-root-hook","kind":"hook","src":"stop:sieve-root#hook","title":"Can you? — How far to test a prime","body":"To check whether 187 is prime, must you try every number up to 186?","cta":"Find out how","level":7,"route":"#/stop/sieve-root"},"idea-sieve-root-case0":{"id":"idea-sieve-root-case0","kind":"idea","src":"stop:sieve-root#case0","title":"How far to test a prime: The root is a prime","body":"13 × 13 = 169 is the last square not past 187, and 13 is itself prime — so 13 is the last one to try.","cta":"See it worked","level":7,"route":"#/stop/sieve-root"},"worked-sieve-root-worked0":{"id":"worked-sieve-root-worked0","kind":"worked","src":"stop:sieve-root#worked0","title":"Worked out — How far to test a prime: The root is a prime","body":"To test whether 187 is prime, what is the biggest prime you might have to try dividing by?: The biggest whole number whose square is not more than 187 → 13 · The biggest prime that is not more than 13 → 13","cta":"Watch it step by step","level":7,"route":"#/stop/sieve-root"},"idea-sieve-root-case1":{"id":"idea-sieve-root-case1","kind":"idea","src":"stop:sieve-root#case1","title":"How far to test a prime: Step down to a prime","body":"14 × 14 = 196 is not past 221, but 14 is not prime. Step down to the biggest prime below it: 13.","cta":"See it worked","level":7,"route":"#/stop/sieve-root"},"why-sieve-root-why1":{"id":"why-sieve-root-why1","kind":"why","src":"stop:sieve-root#why1","title":"Why “How far to test a prime” works","body":"And you only try primes, because every other number is built from prime stones: if 9 went into a number, 3 would go in too, and you would already have found it. That is the idea of the sieve: write out the numbers, cross out the multiples of 2, then of 3, then 5, then 7… Whatever is never crossed out is prime.","cta":"See why","level":7,"route":"#/stop/sieve-root"},"why-sieve-root-why2":{"id":"why-sieve-root-why2","kind":"why","src":"stop:sieve-root#why2","title":"Why “How far to test a prime” works","body":"So the job is: find the square just below your number, take its root, and the largest prime not bigger than that root is the last one you might need. For 187, 13 × 13 = 169 and 14 × 14 = 196, so the last prime to try is 13.","cta":"See why","level":7,"route":"#/stop/sieve-root"},"algebra-sieve-root-alg":{"id":"algebra-sieve-root-alg","kind":"algebra","src":"stop:sieve-root#alg","title":"The algebra behind “How far to test a prime”","body":"n not prime ⇒ n has a prime factor p with p × p ≤ n","cta":"See why","level":7,"route":"#/stop/sieve-root"},"moment-sieve-root-beat3":{"id":"moment-sieve-root-beat3","kind":"moment","src":"story:sieve-root#beat3","badge":{"id":"story","label":"A story"},"title":"The library puzzle — on the notepad","body":"Suki: 14 × 14 is 196, past 187. So if it splits, one factor is 13 or smaller. 14 × 14 = 196","cta":"Read the story","level":7,"route":"#/stop/sieve-root"},"moral-sieve-root-beat5":{"id":"moral-sieve-root-beat5","kind":"moral","src":"story:sieve-root#beat5","badge":{"id":"story","label":"A story"},"title":"Suki, in “The library puzzle”","body":"Not prime. And the biggest prime we could ever have needed was 13.","cta":"Read the story","level":7,"route":"#/stop/sieve-root"},"try-sieve-root-L7":{"id":"try-sieve-root-L7","kind":"try","level":7,"src":"try:sieve-root@7/2#0","title":"How far to test a prime — your turn","route":"#/stop/sieve-root","cta":"Practise this stop","play":{"q":"To test whether 389 is prime, what is the biggest prime you might have to try dividing by?","opts":["19","20","18"],"after":"Find the biggest whole number whose square is not more than your number. You only ever need to try the primes up to that one."}},"trick-cube-and-root-idea":{"id":"trick-cube-and-root-idea","kind":"trick","src":"stop:cube-and-root#idea","title":"Cubes and cube roots","body":"A cube is n × n × n. To undo it, the last digit gives the root's last digit, and the thousands give its tens. Stack 4 layers of a 4-by-4 square and you get a cube of blocks: 4 × 4 × 4 = 64. That is 4³, \"four cubed\" — a length, a width and a height all the same.","cta":"Learn the trick","level":7,"route":"#/stop/cube-and-root"},"story-cube-and-root-open":{"id":"story-cube-and-root-open","kind":"story","src":"story:cube-and-root#open","badge":{"id":"story","label":"A story"},"title":"The sugar-cube tower","body":"In the palace kitchen, Dax builds a giant cube from sugar cubes: 4 long, 4 wide and 4 high. — with Mira and Dax.","art":"art/s-kitchen.webp","cta":"Read the story","level":7,"route":"#/stop/cube-and-root"},"hook-cube-and-root-hook":{"id":"hook-cube-and-root-hook","kind":"hook","src":"stop:cube-and-root#hook","title":"Can you? — Cubes and cube roots","body":"4³ — and then: which number, cubed, makes 42,875?","cta":"Find out how","level":7,"route":"#/stop/cube-and-root"},"idea-cube-and-root-case0":{"id":"idea-cube-and-root-case0","kind":"idea","src":"stop:cube-and-root#case0","title":"Cubes and cube roots: Cubing a number","body":"Three of the same number multiplied: a length, a width and a height all the same.","cta":"See it worked","level":7,"route":"#/stop/cube-and-root"},"worked-cube-and-root-worked0":{"id":"worked-cube-and-root-worked0","kind":"worked","src":"stop:cube-and-root#worked0","title":"Worked out — Cubes and cube roots: Cubing a number","body":"4³: 4 × 4 → 16 · 16 × 4 → 64","cta":"Watch it step by step","level":7,"route":"#/stop/cube-and-root"},"idea-cube-and-root-case1":{"id":"idea-cube-and-root-case1","kind":"idea","src":"stop:cube-and-root#case1","title":"Cubes and cube roots: A small cube root","body":"The last digit of a cube tells you exactly the last digit of its root — 2 and 8 swap, 3 and 7 swap.","cta":"See it worked","level":7,"route":"#/stop/cube-and-root"},"worked-cube-and-root-worked1":{"id":"worked-cube-and-root-worked1","kind":"worked","src":"stop:cube-and-root#worked1","title":"Worked out — Cubes and cube roots: A small cube root","body":"∛343: The last digit of 343 → 3 · So the root ends in → 7 · ∛343 → 7","cta":"Watch it step by step","level":7,"route":"#/stop/cube-and-root"},"idea-cube-and-root-case2":{"id":"idea-cube-and-root-case2","kind":"idea","src":"stop:cube-and-root#case2","title":"Cubes and cube roots: A big cube root","body":"Two digits to find: drop the last three digits for the tens, and use the last digit for the ones.","cta":"See it worked","level":7,"route":"#/stop/cube-and-root"},"worked-cube-and-root-worked2":{"id":"worked-cube-and-root-worked2","kind":"worked","src":"stop:cube-and-root#worked2","title":"Worked out — Cubes and cube roots: A big cube root","body":"∛42,875: Drop the last three digits of 42,875 → 42 · Tens digit: the biggest cube not over that — its root → 3 · The last digit of 42,875 → 5 · So the root ends in → 5 · ∛42,875 → 35","cta":"Watch it step by step","level":7,"route":"#/stop/cube-and-root"},"why-cube-and-root-why1":{"id":"why-cube-and-root-why1","kind":"why","src":"stop:cube-and-root#why1","title":"Why “Cubes and cube roots” works","body":"Cubes have a lovely secret. The last digits of 0³ to 9³ are 0, 1, 8, 7, 4, 5, 6, 3, 2, 9 — all ten different! So the last digit of a cube tells you EXACTLY the last digit of its root. 2 and 8 swap, 3 and 7 swap, the rest stay the same.","cta":"See why","level":7,"route":"#/stop/cube-and-root"},"why-cube-and-root-why2":{"id":"why-cube-and-root-why2","kind":"why","src":"stop:cube-and-root#why2","title":"Why “Cubes and cube roots” works","body":"For the tens digit, drop the last three digits: 42,875 → 42. The biggest cube not over 42 is 27 = 3³, so the tens digit is 3. The cube ends in 5, so the root ends in 5. ∛42,875 = 35. This works because the ones digits only ever affect the last three places… plus a little carrying, which never reaches past the next cube up.","cta":"See why","level":7,"route":"#/stop/cube-and-root"},"algebra-cube-and-root-alg":{"id":"algebra-cube-and-root-alg","kind":"algebra","src":"stop:cube-and-root#alg","title":"The algebra behind “Cubes and cube roots”","body":"n³ = n × n × n   ·   ∛(n³) = n","cta":"See why","level":7,"route":"#/stop/cube-and-root"},"moment-cube-and-root-beat2":{"id":"moment-cube-and-root-beat2","kind":"moment","src":"story:cube-and-root#beat2","badge":{"id":"story","label":"A story"},"title":"The sugar-cube tower — on the notepad","body":"Mira: And there are four layers. That is 4 cubed — four, three times over. 16 × 4 = 64","cta":"Read the story","level":7,"route":"#/stop/cube-and-root"},"moral-cube-and-root-beat5":{"id":"moral-cube-and-root-beat5","kind":"moral","src":"story:cube-and-root#beat5","badge":{"id":"story","label":"A story"},"title":"Dax, in “The sugar-cube tower”","body":"Thirty-five! But mine is smaller: sixty-four cubes, four on a side.","cta":"Read the story","level":7,"route":"#/stop/cube-and-root"},"try-cube-and-root-L7":{"id":"try-cube-and-root-L7","kind":"try","level":7,"src":"try:cube-and-root@7/1#0","title":"Cubes and cube roots — your turn","route":"#/stop/cube-and-root","cta":"Practise this stop","play":{"q":"2³ = ?","opts":["8","4","9"],"after":"A cube is n × n × n. To undo it, the last digit gives the root's last digit, and the thousands give its tens."}},"hook-percent-of-amount-hook":{"id":"hook-percent-of-amount-hook","kind":"hook","src":"stop:percent-of-amount#hook","title":"Can you? — Percentages of an amount","body":"35% of 60 — no calculator on the dock.","cta":"Find out how","level":7,"route":"#/stop/percent-of-amount"},"worked-percent-of-amount-worked0":{"id":"worked-percent-of-amount-worked0","kind":"worked","src":"stop:percent-of-amount#worked0","title":"Worked out — Percentages of an amount: Just 10%","body":"10% of 60: How many tenths make the whole? → 10 · 10% of 60: 60 ÷ 10 → 6","cta":"Watch it step by step","level":7,"route":"#/stop/percent-of-amount"},"worked-percent-of-amount-worked1":{"id":"worked-percent-of-amount-worked1","kind":"worked","src":"stop:percent-of-amount#worked1","title":"Worked out — Percentages of an amount: Lots of 10%","body":"30% of 60: 10% of 60: 60 ÷ 10 → 6 · 30%: 3 lots of 10% → 18","cta":"Watch it step by step","level":7,"route":"#/stop/percent-of-amount"},"worked-percent-of-amount-worked2":{"id":"worked-percent-of-amount-worked2","kind":"worked","src":"stop:percent-of-amount#worked2","title":"Worked out — Percentages of an amount: Just 5%","body":"5% of 60: 10% of 60: 60 ÷ 10 → 6 · 5%: half of 10% → 3","cta":"Watch it step by step","level":7,"route":"#/stop/percent-of-amount"},"worked-percent-of-amount-worked3":{"id":"worked-percent-of-amount-worked3","kind":"worked","src":"stop:percent-of-amount#worked3","title":"Worked out — Percentages of an amount: Tens and a 5","body":"35% of 60: 10% of 60: 60 ÷ 10 → 6 · 30%: 3 lots of 10% → 18 · 5%: half of 10% → 3 · Add them → 21","cta":"Watch it step by step","level":7,"route":"#/stop/percent-of-amount"},"why-percent-of-amount-why2":{"id":"why-percent-of-amount-why2","kind":"why","src":"stop:percent-of-amount#why2","title":"Why “Percentages of an amount” works","body":"The hundred square shows it: each column is 10%, so you can see 35% as three columns and half a column. You never need to know a rule for 35% — only for 10%, and how to double, halve and add.","cta":"See why","level":7,"route":"#/stop/percent-of-amount"},"moment-percent-of-amount-beat3":{"id":"moment-percent-of-amount-beat3","kind":"moment","src":"story:percent-of-amount#beat3","badge":{"id":"story","label":"A story"},"title":"The harbour tax — on the notepad","body":"Rafi: 30% is three of those. 6 × 3 = 18","cta":"Read the story","level":7,"route":"#/stop/percent-of-amount"},"try-percent-of-amount-L7":{"id":"try-percent-of-amount-L7","kind":"try","level":7,"src":"try:percent-of-amount@7/2#0","title":"Percentages of an amount — your turn","route":"#/stop/percent-of-amount","cta":"Practise this stop","play":{"q":"80% of 220 = ?","opts":["176","22","177"],"after":"Find 10% by dividing by 10. Build everything else from 10% and its half, 5%."}},"trick-unitary-method-idea":{"id":"trick-unitary-method-idea","kind":"trick","src":"stop:unitary-method#idea","title":"Find one, then scale","body":"Work out the amount for ONE, then multiply up to as many as you need. A recipe is a ratio: the flour grows exactly as the number of pancakes grows. But 4 and 6 are awkward to jump between — 6 is not a whole number of 4s.","cta":"Learn the trick","level":7,"route":"#/stop/unitary-method"},"story-unitary-method-open":{"id":"story-unitary-method-open","kind":"story","src":"story:unitary-method#open","badge":{"id":"story","label":"A story"},"title":"Pancakes for six","body":"The recipe makes 4 pancakes with 200 g of flour. Six people are coming for breakfast. — with Nova and Suki.","art":"art/s-kitchen.webp","cta":"Read the story","level":7,"route":"#/stop/unitary-method"},"hook-unitary-method-hook":{"id":"hook-unitary-method-hook","kind":"hook","src":"stop:unitary-method#hook","title":"Can you? — Find one, then scale","body":"4 pancakes need 200 g of flour. How much for 6?","cta":"Find out how","level":7,"route":"#/stop/unitary-method"},"worked-unitary-method-worked0":{"id":"worked-unitary-method-worked0","kind":"worked","src":"stop:unitary-method#worked0","title":"Worked out — Find one, then scale","body":"4 pancakes need 200 g of flour. How much for 6?: For 1: 200 ÷ 4 → 50 · For 6: × 6 → 300","cta":"Watch it step by step","level":7,"route":"#/stop/unitary-method"},"why-unitary-method-why1":{"id":"why-unitary-method-why1","kind":"why","src":"stop:unitary-method#why1","title":"Why “Find one, then scale” works","body":"One is the easy stop in the middle. 200 g for 4 pancakes means 200 ÷ 4 = 50 g for one pancake. Then 6 pancakes need 6 × 50 = 300 g.","cta":"See why","level":7,"route":"#/stop/unitary-method"},"why-unitary-method-why2":{"id":"why-unitary-method-why2","kind":"why","src":"stop:unitary-method#why2","title":"Why “Find one, then scale” works","body":"It works for anything that goes up in step — prices, paint, petrol — which is why it is called the unitary method: go to one unit, then out again. Sometimes one unit is a decimal, like 2.5 g, and the method still holds.","cta":"See why","level":7,"route":"#/stop/unitary-method"},"algebra-unitary-method-alg":{"id":"algebra-unitary-method-alg","kind":"algebra","src":"stop:unitary-method#alg","title":"The algebra behind “Find one, then scale”","body":"amount for m = (amount for n ÷ n) × m","cta":"See why","level":7,"route":"#/stop/unitary-method"},"moment-unitary-method-beat3":{"id":"moment-unitary-method-beat3","kind":"moment","src":"story:unitary-method#beat3","badge":{"id":"story","label":"A story"},"title":"Pancakes for six — on the notepad","body":"Nova: 50 g for each pancake. Then six of them… 50 × 6 = 300","cta":"Read the story","level":7,"route":"#/stop/unitary-method"},"moral-unitary-method-beat5":{"id":"moral-unitary-method-beat5","kind":"moral","src":"story:unitary-method#beat5","badge":{"id":"story","label":"A story"},"title":"Nova, in “Pancakes for six”","body":"300 g of flour for six pancakes.","cta":"Read the story","level":7,"route":"#/stop/unitary-method"},"try-unitary-method-L7":{"id":"try-unitary-method-L7","kind":"try","level":7,"src":"try:unitary-method@7/1#0","title":"Find one, then scale — your turn","route":"#/stop/unitary-method","cta":"Practise this stop","play":{"q":"4 bowls of soup need 40 ml of stock. How much for 6?","opts":["60","10","61"],"after":"Work out the amount for ONE, then multiply up to as many as you need."}},"trick-percent-change-idea":{"id":"trick-percent-change-idea","kind":"trick","src":"stop:percent-change#idea","title":"Sales and rises","body":"Find the percentage, then take it off or add it on — or go straight to what is left (80% of the price). 20% off means you do not pay 20 of every 100. So work out 20% of 60 — 12 — and take it away: 48.","cta":"Learn the trick","level":7,"route":"#/stop/percent-change"},"story-percent-change-open":{"id":"story-percent-change-open","kind":"story","src":"story:percent-change#open","badge":{"id":"story","label":"A story"},"title":"The jacket sale","body":"A jacket costs 60 coins. The sign says 20% off. — with Ines and Dax.","art":"art/s-shop.webp","cta":"Read the story","level":7,"route":"#/stop/percent-change"},"idea-percent-change-case0":{"id":"idea-percent-change-case0","kind":"idea","src":"stop:percent-change#case0","title":"Sales and rises: Money off","body":"Find the percentage of the price, then take it away.","cta":"See it worked","level":7,"route":"#/stop/percent-change"},"idea-percent-change-case1":{"id":"idea-percent-change-case1","kind":"idea","src":"stop:percent-change#case1","title":"Sales and rises: Money added","body":"The same two steps upwards: find the percentage, then add it on.","cta":"See it worked","level":7,"route":"#/stop/percent-change"},"idea-percent-change-case2":{"id":"idea-percent-change-case2","kind":"idea","src":"stop:percent-change#case2","title":"Sales and rises: Off, in one step","body":"Think about what you DO pay: 35% off leaves 65%, so find 65% of the price straight away.","cta":"See it worked","level":7,"route":"#/stop/percent-change"},"idea-percent-change-case3":{"id":"idea-percent-change-case3","kind":"idea","src":"stop:percent-change#case3","title":"Sales and rises: Added, in one step","body":"A rise of 15% makes 115% of the old amount — find that directly.","cta":"See it worked","level":7,"route":"#/stop/percent-change"},"why-percent-change-why1":{"id":"why-percent-change-why1","kind":"why","src":"stop:percent-change#why1","title":"Why “Sales and rises” works","body":"Or think about what you DO pay. If 20% is taken off, 80% is left, and 80% of 60 is 48. One step instead of two, and the same answer, because 60 − 20% of 60 is 80% of 60.","cta":"See why","level":7,"route":"#/stop/percent-change"},"algebra-percent-change-alg":{"id":"algebra-percent-change-alg","kind":"algebra","src":"stop:percent-change#alg","title":"The algebra behind “Sales and rises”","body":"n with p% off = n × (100 − p)/100; n with p% added = n × (100 + p)/100","cta":"See why","level":7,"route":"#/stop/percent-change"},"moral-percent-change-beat5":{"id":"moral-percent-change-beat5","kind":"moral","src":"story:percent-change#beat5","badge":{"id":"story","label":"A story"},"title":"Dax, in “The jacket sale”","body":"48 coins, both ways.","cta":"Read the story","level":7,"route":"#/stop/percent-change"},"try-percent-change-L7":{"id":"try-percent-change-L7","kind":"try","level":7,"src":"try:percent-change@7/1#0","title":"Sales and rises — your turn","route":"#/stop/percent-change","cta":"Practise this stop","play":{"q":"200 with 10% off = ?","opts":["180","20","181"],"after":"Find the percentage, then take it off or add it on — or go straight to what is left (80% of the price)."}},"trick-ratio-share-idea":{"id":"trick-ratio-share-idea","kind":"trick","src":"stop:ratio-share#idea","title":"Ratio: simplify and share","body":"Add the parts to find how many equal shares there are. Find one share, then multiply. A ratio 2 : 5 says: for every 2 the first person gets, the second gets 5. Picture handing them out in rounds — each round uses 2 + 5 = 7 mangoes.","cta":"Learn the trick","level":7,"route":"#/stop/ratio-share"},"story-ratio-share-open":{"id":"story-ratio-share-open","kind":"story","src":"story:ratio-share#open","badge":{"id":"story","label":"A story"},"title":"The mango crate","body":"Suki and Rafi fill a crate with 35 mangoes. Rafi picked 2 for every 5 Suki picked, so they share it 2 : 5. — with Rafi and Suki.","art":"art/s-market.webp","cta":"Read the story","level":7,"route":"#/stop/ratio-share"},"worked-ratio-share-worked0":{"id":"worked-ratio-share-worked0","kind":"worked","src":"stop:ratio-share#worked0","title":"Worked out — Ratio: simplify and share: Share in a ratio","body":"Share 35 in the ratio 2 : 5. How much is the larger share?: Parts in one round: 2 + 5 → 7 · One part: 35 ÷ 7 → 5 · The larger share: × 5 → 25","cta":"Watch it step by step","level":7,"route":"#/stop/ratio-share"},"why-ratio-share-why1":{"id":"why-ratio-share-why1","kind":"why","src":"stop:ratio-share#why1","title":"Why “Ratio: simplify and share” works","body":"35 mangoes is 35 ÷ 7 = 5 rounds. So the first person gets 2 × 5 = 10 and the second gets 5 × 5 = 25. Check: 10 + 25 = 35, none left over.","cta":"See why","level":7,"route":"#/stop/ratio-share"},"moment-ratio-share-beat3":{"id":"moment-ratio-share-beat3","kind":"moment","src":"story:ratio-share#beat3","badge":{"id":"story","label":"A story"},"title":"The mango crate — on the notepad","body":"Rafi: Five rounds of 2 for me. 5 × 2 = 10","cta":"Read the story","level":7,"route":"#/stop/ratio-share"},"try-ratio-share-L7":{"id":"try-ratio-share-L7","kind":"try","level":7,"src":"try:ratio-share@7/1#0","title":"Ratio: simplify and share — your turn","route":"#/stop/ratio-share","cta":"Practise this stop","play":{"q":"Share 15 in the ratio 1 : 4. How much is the larger share?","opts":["12","5","3"],"after":"Add the parts to find how many equal shares there are. Find one share, then multiply."}},"trick-speed-distance-time-idea":{"id":"trick-speed-distance-time-idea","kind":"trick","src":"stop:speed-distance-time#idea","title":"Speed, distance and time","body":"Speed is the distance in ONE hour. Distance = speed × time; to find either of the others, divide. 80 km/h means 80 kilometres in every hour. After 2 hours, 160 km; after 3 hours, 240 km. Distance is just the one-hour distance, taken as many times as there are hours.","cta":"Learn the trick","level":7,"route":"#/stop/speed-distance-time"},"story-speed-distance-time-open":{"id":"story-speed-distance-time-open","kind":"story","src":"story:speed-distance-time#open","badge":{"id":"story","label":"A story"},"title":"The coast train","body":"Mira and Theo take the train to the coast: 240 km, and the train runs at 80 km/h. — with Mira and Theo.","art":"art/s-train.webp","cta":"Read the story","level":7,"route":"#/stop/speed-distance-time"},"hook-speed-distance-time-hook":{"id":"hook-speed-distance-time-hook","kind":"hook","src":"stop:speed-distance-time#hook","title":"Can you? — Speed, distance and time","body":"The ferry goes 240 km at 80 km/h. How long does the trip take?","cta":"Find out how","level":7,"route":"#/stop/speed-distance-time"},"idea-speed-distance-time-case0":{"id":"idea-speed-distance-time-case0","kind":"idea","src":"stop:speed-distance-time#case0","title":"Speed, distance and time: How far?","body":"Speed is the distance in one hour, so multiply it by the number of hours.","cta":"See it worked","level":7,"route":"#/stop/speed-distance-time"},"worked-speed-distance-time-worked0":{"id":"worked-speed-distance-time-worked0","kind":"worked","src":"stop:speed-distance-time#worked0","title":"Worked out — Speed, distance and time: How far?","body":"80 km/h for 3 hours. How far, in km?: Km in one hour → 80 · In 3 hours: × 3 → 240","cta":"Watch it step by step","level":7,"route":"#/stop/speed-distance-time"},"idea-speed-distance-time-case1":{"id":"idea-speed-distance-time-case1","kind":"idea","src":"stop:speed-distance-time#case1","title":"Speed, distance and time: How fast?","body":"Share the distance equally between the hours: that is the distance in one hour, the speed.","cta":"See it worked","level":7,"route":"#/stop/speed-distance-time"},"worked-speed-distance-time-worked1":{"id":"worked-speed-distance-time-worked1","kind":"worked","src":"stop:speed-distance-time#worked1","title":"Worked out — Speed, distance and time: How fast?","body":"240 km in 3 hours. What speed, in km/h?: Hours taken → 3 · Km in one hour: 240 ÷ 3 → 80","cta":"Watch it step by step","level":7,"route":"#/stop/speed-distance-time"},"idea-speed-distance-time-case2":{"id":"idea-speed-distance-time-case2","kind":"idea","src":"stop:speed-distance-time#case2","title":"Speed, distance and time: How long?","body":"Ask how many one-hour distances fit into the whole trip.","cta":"See it worked","level":7,"route":"#/stop/speed-distance-time"},"worked-speed-distance-time-worked2":{"id":"worked-speed-distance-time-worked2","kind":"worked","src":"stop:speed-distance-time#worked2","title":"Worked out — Speed, distance and time: How long?","body":"240 km at 80 km/h. How many hours?: Km in one hour → 80 · How many 80s make 240? → 3","cta":"Watch it step by step","level":7,"route":"#/stop/speed-distance-time"},"idea-speed-distance-time-case3":{"id":"idea-speed-distance-time-case3","kind":"idea","src":"stop:speed-distance-time#case3","title":"Speed, distance and time: Minutes, not hours","body":"Turn the minutes into a piece of an hour first: 20 minutes is a third, so you go a third of the speed.","cta":"See it worked","level":7,"route":"#/stop/speed-distance-time"},"worked-speed-distance-time-worked3":{"id":"worked-speed-distance-time-worked3","kind":"worked","src":"stop:speed-distance-time#worked3","title":"Worked out — Speed, distance and time: Minutes, not hours","body":"30 km/h for 20 minutes. How far, in km?: How many 20-minute pieces make an hour? → 3 · Km in 20 minutes: 30 ÷ 3 → 10","cta":"Watch it step by step","level":7,"route":"#/stop/speed-distance-time"},"why-speed-distance-time-why1":{"id":"why-speed-distance-time-why1","kind":"why","src":"stop:speed-distance-time#why1","title":"Why “Speed, distance and time” works","body":"So the other two questions are division. How long for 240 km? How many 80s make 240 — 3 hours. How fast, if 240 km took 3 hours? Share 240 between 3 hours — 80 each hour.","cta":"See why","level":7,"route":"#/stop/speed-distance-time"},"why-speed-distance-time-why2":{"id":"why-speed-distance-time-why2","kind":"why","src":"stop:speed-distance-time#why2","title":"Why “Speed, distance and time” works","body":"Minutes are pieces of an hour. 20 minutes is a third of an hour, so at 30 km/h you go a third of 30: 10 km. Change the time into hours (or pieces of one) before you multiply.","cta":"See why","level":7,"route":"#/stop/speed-distance-time"},"algebra-speed-distance-time-alg":{"id":"algebra-speed-distance-time-alg","kind":"algebra","src":"stop:speed-distance-time#alg","title":"The algebra behind “Speed, distance and time”","body":"d = s × t,  s = d ÷ t,  t = d ÷ s","cta":"See why","level":7,"route":"#/stop/speed-distance-time"},"moment-speed-distance-time-beat3":{"id":"moment-speed-distance-time-beat3","kind":"moment","src":"story:speed-distance-time#beat3","badge":{"id":"story","label":"A story"},"title":"The coast train — on the notepad","body":"Mira: Three hours gets us all the way. 80 × 3 = 240","cta":"Read the story","level":7,"route":"#/stop/speed-distance-time"},"moral-speed-distance-time-beat5":{"id":"moral-speed-distance-time-beat5","kind":"moral","src":"story:speed-distance-time#beat5","badge":{"id":"story","label":"A story"},"title":"Mira, in “The coast train”","body":"Three hours. Time for a sandwich.","cta":"Read the story","level":7,"route":"#/stop/speed-distance-time"},"try-speed-distance-time-L7":{"id":"try-speed-distance-time-L7","kind":"try","level":7,"src":"try:speed-distance-time@7/1#0","title":"Speed, distance and time — your turn","route":"#/stop/speed-distance-time","cta":"Practise this stop","play":{"q":"150 km in 3 hours. What speed, in km/h?","opts":["50","3","51"],"after":"Speed is the distance in ONE hour. Distance = speed × time; to find either of the others, divide."}},"trick-substitute-idea":{"id":"trick-substitute-idea","kind":"trick","src":"stop:substitute#idea","title":"Letters for numbers","body":"A letter is a box holding a number. Put the number in the box, then do the sum — times before plus. 3n means 3 × n — in algebra we leave the × out so it does not get mixed up with the letter x. So when n = 4, 3n + 2 is 3 × 4 + 2 = 12 + 2 = 14.","cta":"Learn the trick","level":7,"route":"#/stop/substitute"},"story-substitute-open":{"id":"story-substitute-open","kind":"story","src":"story:substitute#open","badge":{"id":"story","label":"A story"},"title":"The matchstick pattern","body":"Pip builds a row of triangles out of matchsticks. Kwame writes on the board: matches = 3n + 2, for n triangles. — with Kwame and Pip.","art":"art/s-room.webp","cta":"Read the story","level":7,"route":"#/stop/substitute"},"idea-substitute-case0":{"id":"idea-substitute-case0","kind":"idea","src":"stop:substitute#case0","title":"Letters for numbers: Times, then add","body":"3n is 3 × n — the × is hidden. Do the multiplying first, then the adding or taking away.","cta":"See it worked","level":7,"route":"#/stop/substitute"},"idea-substitute-case1":{"id":"idea-substitute-case1","kind":"idea","src":"stop:substitute#case1","title":"Letters for numbers: Brackets first","body":"A number outside brackets multiplies the whole bracket, so work out the inside first.","cta":"See it worked","level":7,"route":"#/stop/substitute"},"idea-substitute-case2":{"id":"idea-substitute-case2","kind":"idea","src":"stop:substitute#case2","title":"Letters for numbers: Squaring a negative","body":"n² is n × n. With a negative in the box, negative times negative is positive — so the square is never below zero.","cta":"See it worked","level":7,"route":"#/stop/substitute"},"idea-substitute-case3":{"id":"idea-substitute-case3","kind":"idea","src":"stop:substitute#case3","title":"Letters for numbers: Two letters","body":"Each letter has its own number. Fill both boxes, work out each term, then add — a negative term takes away.","cta":"See it worked","level":7,"route":"#/stop/substitute"},"why-substitute-why1":{"id":"why-substitute-why1","kind":"why","src":"stop:substitute#why1","title":"Why “Letters for numbers” works","body":"Why use a letter at all? Because one expression can describe a whole pattern. \"Triangles in a row of n tiles use 3n + 2 matches\" works for 4 tiles, for 40, for 400 — you only swap the number in the box.","cta":"See why","level":7,"route":"#/stop/substitute"},"algebra-substitute-alg":{"id":"algebra-substitute-alg","kind":"algebra","src":"stop:substitute#alg","title":"The algebra behind “Letters for numbers”","body":"an + b with n = k  →  a × k + b","cta":"See why","level":7,"route":"#/stop/substitute"},"moral-substitute-beat5":{"id":"moral-substitute-beat5","kind":"moral","src":"story:substitute#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “The matchstick pattern”","body":"Fourteen matches! And the same rule tells me 40 triangles would need 122.","cta":"Read the story","level":7,"route":"#/stop/substitute"},"try-substitute-L7":{"id":"try-substitute-L7","kind":"try","level":7,"src":"try:substitute@7/1#0","title":"Letters for numbers — your turn","route":"#/stop/substitute","cta":"Practise this stop","play":{"q":"If n = 8, what is 9n + 10?","opts":["82","72","83"],"after":"A letter is a box holding a number. Put the number in the box, then do the sum — times before plus."}},"trick-like-terms-idea":{"id":"trick-like-terms-idea","kind":"trick","src":"stop:like-terms#idea","title":"Collecting like terms","body":"Terms with the same letter are the same kind of thing: add their numbers. Different letters stay apart. Think of x as an apple and y as a banana. 3 apples, 2 bananas, 4 more apples and 1 more banana: that is 7 apples and 3 bananas, 7x + 3y. You cannot add apples to bananas and call them 10 \"applebananas\" — so 10xy is wrong.","cta":"Learn the trick","level":7,"route":"#/stop/like-terms"},"story-like-terms-open":{"id":"story-like-terms-open","kind":"story","src":"story:like-terms#open","badge":{"id":"story","label":"A story"},"title":"The fruit basket","body":"Ines writes the market order in algebra: x for a crate of apples, y for bananas. 3x + 2y + 4x + y. — with Ines and Nova.","art":"art/s-market.webp","cta":"Read the story","level":7,"route":"#/stop/like-terms"},"idea-like-terms-case0":{"id":"idea-like-terms-case0","kind":"idea","src":"stop:like-terms#case0","title":"Collecting like terms: One letter","body":"Every term is the same kind of thing, so just add the numbers in front. A letter on its own means 1 of it.","cta":"See it worked","level":7,"route":"#/stop/like-terms"},"idea-like-terms-case1":{"id":"idea-like-terms-case1","kind":"idea","src":"stop:like-terms#case1","title":"Collecting like terms: Two letters","body":"Keep x's with x's and y's with y's. The answer has two terms — you cannot add apples to bananas.","cta":"See it worked","level":7,"route":"#/stop/like-terms"},"idea-like-terms-case2":{"id":"idea-like-terms-case2","kind":"idea","src":"stop:like-terms#case2","title":"Collecting like terms: Taking away x's","body":"The minus sign belongs to the term after it. More x's taken than you had leaves a negative number in front.","cta":"See it worked","level":7,"route":"#/stop/like-terms"},"why-like-terms-why1":{"id":"why-like-terms-why1","kind":"why","src":"stop:like-terms#why1","title":"Why “Collecting like terms” works","body":"This works because x is the same number every time it appears. 3x + 4x means 3 lots of that number and 4 more lots of it: 7 lots, whatever it is.","cta":"See why","level":7,"route":"#/stop/like-terms"},"algebra-like-terms-alg":{"id":"algebra-like-terms-alg","kind":"algebra","src":"stop:like-terms#alg","title":"The algebra behind “Collecting like terms”","body":"ax + bx = (a + b)x","cta":"See why","level":7,"route":"#/stop/like-terms"},"moral-like-terms-beat5":{"id":"moral-like-terms-beat5","kind":"moral","src":"story:like-terms#beat5","badge":{"id":"story","label":"A story"},"title":"Nova, in “The fruit basket”","body":"Seven crates of apples and three of bananas. Like with like.","cta":"Read the story","level":7,"route":"#/stop/like-terms"},"try-like-terms-L7":{"id":"try-like-terms-L7","kind":"try","level":7,"src":"try:like-terms@7/1#0","title":"Collecting like terms — your turn","route":"#/stop/like-terms","cta":"Practise this stop","play":{"q":"6x + 4x + x = □x. What goes in the box?","opts":["11","10","12"],"after":"Terms with the same letter are the same kind of thing: add their numbers. Different letters stay apart."}},"trick-solve-balance-idea":{"id":"trick-solve-balance-idea","kind":"trick","src":"stop:solve-balance#idea","title":"Solving equations on a balance","body":"An equation is a level balance. Do the same to both sides, undoing the last thing first, until x stands alone. Picture a balance: three bags of x sweets and 4 loose sweets on one side, 19 sweets on the other, perfectly level. Take 4 loose sweets off BOTH sides and it is still level: 3 bags balance 15 sweets.","cta":"Learn the trick","level":7,"route":"#/stop/solve-balance"},"story-solve-balance-open":{"id":"story-solve-balance-open","kind":"story","src":"story:solve-balance#open","badge":{"id":"story","label":"A story"},"title":"The weighing scale","body":"On the shop scale: 3 bags of marbles and 4 loose marbles balance 19 loose marbles. Every bag holds the same. — with Kwame and Suki.","art":"art/s-shop.webp","cta":"Read the story","level":7,"route":"#/stop/solve-balance"},"idea-solve-balance-case0":{"id":"idea-solve-balance-case0","kind":"idea","src":"stop:solve-balance#case0","title":"Solving equations on a balance: Undo an add","body":"Something was added to x. Take the same amount off both sides and x stands alone.","cta":"See it worked","level":7,"route":"#/stop/solve-balance"},"idea-solve-balance-case1":{"id":"idea-solve-balance-case1","kind":"idea","src":"stop:solve-balance#case1","title":"Solving equations on a balance: Undo a times","body":"4x means four x's. Share both sides into four equal parts to find one x.","cta":"See it worked","level":7,"route":"#/stop/solve-balance"},"idea-solve-balance-case2":{"id":"idea-solve-balance-case2","kind":"idea","src":"stop:solve-balance#case2","title":"Solving equations on a balance: Two steps","body":"Undo the last thing first: take away the plain number, THEN share. Doing it the other way round breaks the balance sum.","cta":"See it worked","level":7,"route":"#/stop/solve-balance"},"idea-solve-balance-case3":{"id":"idea-solve-balance-case3","kind":"idea","src":"stop:solve-balance#case3","title":"Solving equations on a balance: Words into an equation","body":"Write the words as an equation first. Here a number was taken away, so undo it by adding to both sides.","cta":"See it worked","level":7,"route":"#/stop/solve-balance"},"why-solve-balance-why1":{"id":"why-solve-balance-why1","kind":"why","src":"stop:solve-balance#why1","title":"Why “Solving equations on a balance” works","body":"Now split both sides into three equal shares: one bag balances 5 sweets. So x = 5. Whatever you do to one side, you do to the other — that is the one rule, and it is why the answer is guaranteed to be right.","cta":"See why","level":7,"route":"#/stop/solve-balance"},"algebra-solve-balance-alg":{"id":"algebra-solve-balance-alg","kind":"algebra","src":"stop:solve-balance#alg","title":"The algebra behind “Solving equations on a balance”","body":"ax + b = c  ⇒  x = (c − b) ÷ a","cta":"See why","level":7,"route":"#/stop/solve-balance"},"moral-solve-balance-beat5":{"id":"moral-solve-balance-beat5","kind":"moral","src":"story:solve-balance#beat5","badge":{"id":"story","label":"A story"},"title":"Suki, in “The weighing scale”","body":"Five marbles in each bag. Same to both sides, always.","cta":"Read the story","level":7,"route":"#/stop/solve-balance"},"try-solve-balance-L7":{"id":"try-solve-balance-L7","kind":"try","level":7,"src":"try:solve-balance@7/1#0","title":"Solving equations on a balance — your turn","route":"#/stop/solve-balance","cta":"Practise this stop","play":{"q":"x + 17 = 23. What is x?","opts":["6","17","7"],"after":"An equation is a level balance. Do the same to both sides, undoing the last thing first, until x stands alone."}},"trick-chance-fraction-idea":{"id":"trick-chance-fraction-idea","kind":"trick","src":"stop:chance-fraction#idea","title":"Chance as a fraction","body":"Probability = the ways it can happen ÷ all the equally likely ways. Write it as a fraction. If every part of the spinner is the same size, every part is equally likely to be where the arrow stops. So each of the 8 parts gets exactly one eighth of the chance.","cta":"Learn the trick","level":7,"route":"#/stop/chance-fraction"},"story-chance-fraction-open":{"id":"story-chance-fraction-open","kind":"story","src":"story:chance-fraction#open","badge":{"id":"story","label":"A story"},"title":"The spinner stall","body":"The spinner has 8 equal parts. 3 are blue, and blue wins a goldfish balloon. — with Ines and Dax.","art":"art/s-carnival.webp","cta":"Read the story","level":7,"route":"#/stop/chance-fraction"},"hook-chance-fraction-hook":{"id":"hook-chance-fraction-hook","kind":"hook","src":"stop:chance-fraction#hook","title":"Can you? — Chance as a fraction","body":"A spinner with 8 equal parts, 3 of them blue. What is the chance of blue — as a number?","cta":"Find out how","level":7,"route":"#/stop/chance-fraction"},"idea-chance-fraction-case0":{"id":"idea-chance-fraction-case0","kind":"idea","src":"stop:chance-fraction#case0","title":"Chance as a fraction: The chance of it","body":"The bottom of the fraction counts every equal part; the top counts the parts you want.","cta":"See it worked","level":7,"route":"#/stop/chance-fraction"},"worked-chance-fraction-worked0":{"id":"worked-chance-fraction-worked0","kind":"worked","src":"stop:chance-fraction#worked0","title":"Worked out — Chance as a fraction: The chance of it","body":"A spinner has 8 equal parts: 3 blue and 5 yellow. What is the chance of blue?: How many are blue? → 3 · How many equal parts altogether? → 8 · The chance, as a fraction → 3/8","cta":"Watch it step by step","level":7,"route":"#/stop/chance-fraction"},"idea-chance-fraction-case1":{"id":"idea-chance-fraction-case1","kind":"idea","src":"stop:chance-fraction#case1","title":"Chance as a fraction: The chance of NOT","body":"Count the parts that are anything else. The two chances always add up to a whole: 3/8 blue leaves 5/8 not blue.","cta":"See it worked","level":7,"route":"#/stop/chance-fraction"},"why-chance-fraction-why1":{"id":"why-chance-fraction-why1","kind":"why","src":"stop:chance-fraction#why1","title":"Why “Chance as a fraction” works","body":"Three of those eighths are blue, so the chance of blue is 3/8. The bottom of the fraction counts everything that could happen; the top counts the ones you want.","cta":"See why","level":7,"route":"#/stop/chance-fraction"},"why-chance-fraction-why2":{"id":"why-chance-fraction-why2","kind":"why","src":"stop:chance-fraction#why2","title":"Why “Chance as a fraction” works","body":"That is why chance is always between 0 and 1: 0/8 is impossible, 8/8 is certain, and 4/8 — a half — is the even chance in the middle. The chance of NOT blue is whatever is left: 5/8.","cta":"See why","level":7,"route":"#/stop/chance-fraction"},"algebra-chance-fraction-alg":{"id":"algebra-chance-fraction-alg","kind":"algebra","src":"stop:chance-fraction#alg","title":"The algebra behind “Chance as a fraction”","body":"P(event) = ways it can happen ÷ all equally likely ways","cta":"See why","level":7,"route":"#/stop/chance-fraction"},"moment-chance-fraction-beat3":{"id":"moment-chance-fraction-beat3","kind":"moment","src":"story:chance-fraction#beat3","badge":{"id":"story","label":"A story"},"title":"The spinner stall — on the notepad","body":"Ines: Three of the parts are blue — three eighths. 3 × 0.125 = 0.375","cta":"Read the story","level":7,"route":"#/stop/chance-fraction"},"moral-chance-fraction-beat5":{"id":"moral-chance-fraction-beat5","kind":"moral","src":"story:chance-fraction#beat5","badge":{"id":"story","label":"A story"},"title":"Ines, in “The spinner stall”","body":"Five eighths. Your chance of blue is 3 out of 8.","cta":"Read the story","level":7,"route":"#/stop/chance-fraction"},"try-chance-fraction-L7":{"id":"try-chance-fraction-L7","kind":"try","level":7,"src":"try:chance-fraction@7/1#0","title":"Chance as a fraction — your turn","route":"#/stop/chance-fraction","cta":"Practise this stop","play":{"q":"A spinner has 3 equal parts: 1 blue and 2 yellow. What is the chance of yellow?","opts":["2/3","2","3"],"after":"Probability = the ways it can happen ÷ all the equally likely ways. Write it as a fraction."}},"trick-list-outcomes-idea":{"id":"trick-list-outcomes-idea","kind":"trick","src":"stop:list-outcomes#idea","title":"Counting all the ways","body":"For every choice of the first thing, there are all the choices of the second: multiply. List them in a system so none is missed: take the first top and try it with every skirt — that is 4 outfits. The second top makes 4 more, the third another 4. Three rows of 4 is 3 × 4.","cta":"Learn the trick","level":7,"route":"#/stop/list-outcomes"},"story-list-outcomes-open":{"id":"story-list-outcomes-open","kind":"story","src":"story:list-outcomes#open","badge":{"id":"story","label":"A story"},"title":"Parade costumes","body":"Before the parade, the costume box holds 3 tops and 4 skirts. Nova wants a different outfit every day. — with Mira and Nova.","art":"art/s-hall.webp","cta":"Read the story","level":7,"route":"#/stop/list-outcomes"},"hook-list-outcomes-hook":{"id":"hook-list-outcomes-hook","kind":"hook","src":"stop:list-outcomes#hook","title":"Can you? — Counting all the ways","body":"3 tops and 4 skirts for the parade. How many different outfits — without drawing them all?","cta":"Find out how","level":7,"route":"#/stop/list-outcomes"},"idea-list-outcomes-case0":{"id":"idea-list-outcomes-case0","kind":"idea","src":"stop:list-outcomes#case0","title":"Counting all the ways: Two choices: multiply","body":"Every top goes with every skirt, so it is rows of the same size: 3 rows of 4.","cta":"See it worked","level":7,"route":"#/stop/list-outcomes"},"worked-list-outcomes-worked0":{"id":"worked-list-outcomes-worked0","kind":"worked","src":"stop:list-outcomes#worked0","title":"Worked out — Counting all the ways: Two choices: multiply","body":"3 tops and 4 skirts for the parade. How many different outfits?: How many tops? → 3 · How many skirts go with each? → 4 · 3 × 4 → 12","cta":"Watch it step by step","level":7,"route":"#/stop/list-outcomes"},"idea-list-outcomes-case1":{"id":"idea-list-outcomes-case1","kind":"idea","src":"stop:list-outcomes#case1","title":"Counting all the ways: Three choices","body":"Every hat-and-mask pair goes with every cape, so multiply again for the third choice.","cta":"See it worked","level":7,"route":"#/stop/list-outcomes"},"worked-list-outcomes-worked1":{"id":"worked-list-outcomes-worked1","kind":"worked","src":"stop:list-outcomes#worked1","title":"Worked out — Counting all the ways: Three choices","body":"2 hats, 3 masks and 4 capes. One of each — how many different costumes?: Hats and masks: 2 × 3 → 6 · With every one of those, 4 capes: 6 × 4 → 24","cta":"Watch it step by step","level":7,"route":"#/stop/list-outcomes"},"idea-list-outcomes-case2":{"id":"idea-list-outcomes-case2","kind":"idea","src":"stop:list-outcomes#case2","title":"Counting all the ways: Handshakes","body":"A handshake between two people is ONE handshake, but counting from both ends counts it twice — so halve it.","cta":"See it worked","level":7,"route":"#/stop/list-outcomes"},"worked-list-outcomes-worked2":{"id":"worked-list-outcomes-worked2","kind":"worked","src":"stop:list-outcomes#worked2","title":"Worked out — Counting all the ways: Handshakes","body":"5 friends meet at the carnival. Everyone shakes hands once with everyone else. How many handshakes?: How many hands does each person shake? → 4 · 5 × 4 → 20 · Each handshake was counted twice — halve it → 10","cta":"Watch it step by step","level":7,"route":"#/stop/list-outcomes"},"why-list-outcomes-why1":{"id":"why-list-outcomes-why1","kind":"why","src":"stop:list-outcomes#why1","title":"Why “Counting all the ways” works","body":"The same works for chance. A coin can land 2 ways and a dice 6 ways, and every coin result goes with every dice result: 2 × 6 = 12 outcomes, like a table with 2 rows and 6 columns.","cta":"See why","level":7,"route":"#/stop/list-outcomes"},"why-list-outcomes-why2":{"id":"why-list-outcomes-why2","kind":"why","src":"stop:list-outcomes#why2","title":"Why “Counting all the ways” works","body":"Handshakes are different, because two people shaking hands is ONE handshake, not two. Each of 6 people shakes 5 hands, which counts 6 × 5 = 30 — but every handshake was counted from both ends, so there are only 15.","cta":"See why","level":7,"route":"#/stop/list-outcomes"},"algebra-list-outcomes-alg":{"id":"algebra-list-outcomes-alg","kind":"algebra","src":"stop:list-outcomes#alg","title":"The algebra behind “Counting all the ways”","body":"a choices then b choices: a × b · handshakes among n people: n(n − 1) ÷ 2","cta":"See why","level":7,"route":"#/stop/list-outcomes"},"moment-list-outcomes-beat3":{"id":"moment-list-outcomes-beat3","kind":"moment","src":"story:list-outcomes#beat3","badge":{"id":"story","label":"A story"},"title":"Parade costumes — on the notepad","body":"Nova: Then the second top with all 4, and the third with all 4. 4 + 4 + 4 = 12","cta":"Read the story","level":7,"route":"#/stop/list-outcomes"},"moral-list-outcomes-beat5":{"id":"moral-list-outcomes-beat5","kind":"moral","src":"story:list-outcomes#beat5","badge":{"id":"story","label":"A story"},"title":"Nova, in “Parade costumes”","body":"Twelve outfits — twelve days of parades!","cta":"Read the story","level":7,"route":"#/stop/list-outcomes"},"try-list-outcomes-L7":{"id":"try-list-outcomes-L7","kind":"try","level":7,"src":"try:list-outcomes@7/1#0","title":"Counting all the ways — your turn","route":"#/stop/list-outcomes","cta":"Practise this stop","play":{"q":"Toss two coins. How many different outcomes are there?","opts":["4","2","5"],"after":"For every choice of the first thing, there are all the choices of the second: multiply."}},"hook-think-of-a-number-hook":{"id":"hook-think-of-a-number-hook","kind":"hook","src":"stop:think-of-a-number#hook","title":"Can you? — Working backwards","body":"I think of a number, times it by 3, add 4, and get 19. What was my number?","cta":"Find out how","level":7,"route":"#/stop/think-of-a-number"},"why-think-of-a-number-why1":{"id":"why-think-of-a-number-why1","kind":"why","src":"stop:think-of-a-number#why1","title":"Why “Working backwards” works","body":"Every step has an opposite that cancels it. Adding 4 then taking 4 away leaves you where you were; times 3 then divide by 3 does too. So 19 − 4 = 15 undoes the adding, and 15 ÷ 3 = 5 undoes the multiplying.","cta":"See why","level":7,"route":"#/stop/think-of-a-number"},"algebra-think-of-a-number-alg":{"id":"algebra-think-of-a-number-alg","kind":"algebra","src":"stop:think-of-a-number#alg","title":"The algebra behind “Working backwards”","body":"((x × a) + b = c) ⇒ x = (c − b) ÷ a","cta":"See why","level":7,"route":"#/stop/think-of-a-number"},"moral-think-of-a-number-beat5":{"id":"moral-think-of-a-number-beat5","kind":"moral","src":"story:think-of-a-number#beat5","badge":{"id":"story","label":"A story"},"title":"Vesper, in “The mind-reader”","body":"Backwards, last step first. Check it.","cta":"Read the story","level":7,"route":"#/stop/think-of-a-number"},"try-think-of-a-number-L7":{"id":"try-think-of-a-number-L7","kind":"try","level":7,"src":"try:think-of-a-number@7/2#0","title":"Working backwards — your turn","route":"#/stop/think-of-a-number","cta":"Practise this stop","play":{"q":"? → × 7 → − 9 → 5. What number went in?","opts":["2","14","3"],"after":"Start at the end and undo each step, last one first: undo + with −, and × with ÷."}},"trick-factorials-idea":{"id":"trick-factorials-idea","kind":"trick","src":"stop:factorials#idea","title":"Factorials","body":"n! means n × (n − 1) × … × 2 × 1: multiply every whole number from n down to 1. Line up 4 friends. Any of the 4 can stand first. Whoever is first, any of the 3 left can stand second, then either of the last 2, and the last friend has no choice at all. So there are 4 × 3 × 2 × 1 = 24 line-ups. That product turns up so often it has a short name: 4 factorial, written 4!.","cta":"Learn the trick","level":7,"route":"#/stop/factorials"},"story-factorials-open":{"id":"story-factorials-open","kind":"story","src":"story:factorials#open","badge":{"id":"story","label":"A story"},"title":"The photo booth","body":"At the fair photo booth, 5 friends want a picture in a row. Dax wants one photo for every different order. — with Rafi and Dax.","art":"art/s-fair.webp","cta":"Read the story","level":7,"route":"#/stop/factorials"},"hook-factorials-hook":{"id":"hook-factorials-hook","kind":"hook","src":"stop:factorials#hook","title":"Can you? — Factorials","body":"How many ways can 5 friends line up for a photo? Now try 10 friends — without listing them.","cta":"Find out how","level":7,"route":"#/stop/factorials"},"idea-factorials-case0":{"id":"idea-factorials-case0","kind":"idea","src":"stop:factorials#case0","title":"Factorials: Work out n!","body":"Build it upwards: each factorial is the one before, times the next number. 2! = 2, 3! = 3 × 2!, 4! = 4 × 3!…","cta":"See it worked","level":7,"route":"#/stop/factorials"},"worked-factorials-worked0":{"id":"worked-factorials-worked0","kind":"worked","src":"stop:factorials#worked0","title":"Worked out — Factorials: Work out n!","body":"Work out 5!: 2! = 2 × 1 → 2 · 3! = 3 × 2! → 6 · 4! = 4 × 3! → 24 · 5! = 5 × 4! → 120","cta":"Watch it step by step","level":7,"route":"#/stop/factorials"},"idea-factorials-case1":{"id":"idea-factorials-case1","kind":"idea","src":"stop:factorials#case1","title":"Factorials: Divide: cancel first","body":"6! is hiding inside 8!, so it cancels. Only the numbers from 8 down to 7 are left to multiply.","cta":"See it worked","level":7,"route":"#/stop/factorials"},"worked-factorials-worked1":{"id":"worked-factorials-worked1","kind":"worked","src":"stop:factorials#worked1","title":"Worked out — Factorials: Divide: cancel first","body":"Work out 8! ÷ 6!: 6! cancels. How many numbers are left, counting down from 8? → 2 · 8 × 7 → 56","cta":"Watch it step by step","level":7,"route":"#/stop/factorials"},"idea-factorials-case2":{"id":"idea-factorials-case2","kind":"idea","src":"stop:factorials#case2","title":"Factorials: Zero factorial","body":"Walk the pattern down, dividing as you go: 1! ÷ 1 = 0!. So 0! is 1 — one way to line up nobody.","cta":"See it worked","level":7,"route":"#/stop/factorials"},"worked-factorials-worked2":{"id":"worked-factorials-worked2","kind":"worked","src":"stop:factorials#worked2","title":"Worked out — Factorials: Zero factorial","body":"Work out 3! + 0!: 2! = 2 × 1 → 2 · 3! = 3 × 2! → 6 · 0! — walk the pattern down to it → 1 · 6 + 1 → 7","cta":"Watch it step by step","level":7,"route":"#/stop/factorials"},"why-factorials-why1":{"id":"why-factorials-why1","kind":"why","src":"stop:factorials#why1","title":"Why “Factorials” works","body":"Every factorial holds the one below it: 5! = 5 × 4 × 3 × 2 × 1 = 5 × 4!. That is why 8! ÷ 6! is easy. 6! sits inside 8!, so it cancels, and only 8 × 7 = 56 is left. Never work out two huge numbers just to divide one by the other.","cta":"See why","level":7,"route":"#/stop/factorials"},"why-factorials-why2":{"id":"why-factorials-why2","kind":"why","src":"stop:factorials#why2","title":"Why “Factorials” works","body":"Walk the pattern down: 4! = 24, and dividing by 4 gives 3! = 6; divide by 3 and 2! = 2; divide by 2 and 1! = 1. One more step, divide by 1, gives 0! = 1. It is not a rule someone made up — it is the only value that keeps the pattern going, and there really is exactly one way to line up nobody.","cta":"See why","level":7,"route":"#/stop/factorials"},"algebra-factorials-alg":{"id":"algebra-factorials-alg","kind":"algebra","src":"stop:factorials#alg","title":"The algebra behind “Factorials”","body":"n! = n × (n − 1) × … × 2 × 1 = n × (n − 1)! · 0! = 1","cta":"See why","level":7,"route":"#/stop/factorials"},"moment-factorials-beat3":{"id":"moment-factorials-beat3","kind":"moment","src":"story:factorials#beat3","badge":{"id":"story","label":"A story"},"title":"The photo booth — on the notepad","body":"Dax: Twenty already, and that is only two places. Then 3 for the middle, 2, and the last one has no choice. 20 × 3 × 2 × 1 = 120","cta":"Read the story","level":7,"route":"#/stop/factorials"},"moral-factorials-beat6":{"id":"moral-factorials-beat6","kind":"moral","src":"story:factorials#beat6","badge":{"id":"story","label":"A story"},"title":"Rafi, in “The photo booth”","body":"Five factorial, written 5 with an exclamation mark. 120 orders.","cta":"Read the story","level":7,"route":"#/stop/factorials"},"try-factorials-L7":{"id":"try-factorials-L7","kind":"try","level":7,"src":"try:factorials@7/1#0","title":"Factorials — your turn","route":"#/stop/factorials","cta":"Practise this stop","play":{"q":"Work out 6! = ?","opts":["720","120","721"],"after":"n! means n × (n − 1) × … × 2 × 1: multiply every whole number from n down to 1."}},"trick-arrange-all-idea":{"id":"trick-arrange-all-idea","kind":"trick","src":"stop:arrange-all#idea","title":"Putting things in order","body":"Fill the places one at a time: n choices for the first, n − 1 for the next, down to 1. A place that is already decided has only 1 choice. Think of a row of empty places. The first place can take any of the n things. Once it is filled, the second place has n − 1 left — and that is true whichever thing went first, so every first choice brings the same number of second choices. Multiply all the way down: n × (n − 1) × … × 1 = n!.","cta":"Learn the trick","level":7,"route":"#/stop/arrange-all"},"story-arrange-all-open":{"id":"story-arrange-all-open","kind":"story","src":"story:arrange-all#open","badge":{"id":"story","label":"A story"},"title":"The dodgem queue","body":"Pip, Suki, Nova and Rafi queue for the dodgems. Pip says he must be at the front. — with Pip and Suki.","art":"art/s-carnival.webp","cta":"Read the story","level":7,"route":"#/stop/arrange-all"},"idea-arrange-all-case0":{"id":"idea-arrange-all-case0","kind":"idea","src":"stop:arrange-all#case0","title":"Putting things in order: Everyone in a row","body":"n choices for the first place, one fewer for each place after it, down to 1: that is n!.","cta":"See it worked","level":7,"route":"#/stop/arrange-all"},"idea-arrange-all-case1":{"id":"idea-arrange-all-case1","kind":"idea","src":"stop:arrange-all#case1","title":"Putting things in order: One place fixed","body":"Pip is at the front already, so that place has 1 choice. Only the others move: (n − 1)!.","cta":"See it worked","level":7,"route":"#/stop/arrange-all"},"idea-arrange-all-case2":{"id":"idea-arrange-all-case2","kind":"idea","src":"stop:arrange-all#case2","title":"Putting things in order: First from a few","body":"Fill the fussy place first: 2 sprinters could run first. Then the rest go in any order.","cta":"See it worked","level":7,"route":"#/stop/arrange-all"},"why-arrange-all-why1":{"id":"why-arrange-all-why1","kind":"why","src":"stop:arrange-all#why1","title":"Why “Putting things in order” works","body":"If Pip must be at the front, the first place has only 1 choice. Just the other n − 1 are free to move, so there are (n − 1)! orders. Check it with 3 friends: with Pip in front, only the other two can swap — 2 orders, and 2! = 2.","cta":"See why","level":7,"route":"#/stop/arrange-all"},"algebra-arrange-all-alg":{"id":"algebra-arrange-all-alg","kind":"algebra","src":"stop:arrange-all#alg","title":"The algebra behind “Putting things in order”","body":"n things in a row: n! · one place fixed: (n − 1)! · first place from k of them: k × (n − 1)!","cta":"See why","level":7,"route":"#/stop/arrange-all"},"moral-arrange-all-beat5":{"id":"moral-arrange-all-beat5","kind":"moral","src":"story:arrange-all#beat5","badge":{"id":"story","label":"A story"},"title":"Pip, in “The dodgem queue”","body":"So my rule keeps a quarter of them: 6 orders, every one with me in front.","cta":"Read the story","level":7,"route":"#/stop/arrange-all"},"try-arrange-all-L7":{"id":"try-arrange-all-L7","kind":"try","level":7,"src":"try:arrange-all@7/1#0","title":"Putting things in order — your turn","route":"#/stop/arrange-all","cta":"Practise this stop","play":{"q":"5 different prizes go in a row on the hoopla shelf. In how many different orders can they go?","opts":["120","5","24"],"after":"Fill the places one at a time: n choices for the first, n − 1 for the next, down to 1. A place that is already decided has only 1 choice."}},"word-arrangement":{"id":"word-arrangement","kind":"word","src":"dictionary:arrangement#def","title":"arrangement","body":"One way of putting things in order, in a row or in named places. For example: A, B and C can go in 6 orders: ABC, ACB, BAC, BCA, CAB and CBA — that is 3! = 6.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":7},"wordq-arrangement":{"id":"wordq-arrangement","kind":"wordq","src":"dictionary:arrangement#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “A, B and C can go in 6 orders: ABC, ACB, BAC, BCA, CAB and CBA — that is 3! = 6.”","opts":["arrangement","net","integer"],"after":"arrangement: One way of putting things in order, in a row or in named places."},"level":7},"word-compound-measure":{"id":"word-compound-measure","kind":"word","src":"dictionary:compound measure#def","title":"compound measure","body":"A measure made from two others, like kilometres per hour or grams per cubic centimetre. For example: 90 km/h means 90 km in each hour.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":7},"wordq-compound-measure":{"id":"wordq-compound-measure","kind":"wordq","src":"dictionary:compound measure#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “90 km/h means 90 km in each hour.”","opts":["compound measure","inverse operation","exterior angle"],"after":"compound measure: A measure made from two others, like kilometres per hour or grams per cubic centimetre."},"level":7},"word-cube-number":{"id":"word-cube-number","kind":"word","src":"dictionary:cube number#def","title":"cube number","body":"A whole number multiplied by itself and then by itself again — that many small blocks build one big block with equal edges. For example: 64 = 4 × 4 × 4.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":7},"wordq-cube-number":{"id":"wordq-cube-number","kind":"wordq","src":"dictionary:cube number#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “64 = 4 × 4 × 4.”","opts":["cube number","perpendicular height","density"],"after":"cube number: A whole number multiplied by itself and then by itself again — that many small blocks build one big block with equal edges."},"level":7},"word-cube-root":{"id":"word-cube-root","kind":"word","src":"dictionary:cube root#def","title":"cube root","body":"The number which, used three times in a multiplication, gives the one you started with. Sign: ∛. For example: ∛125 = 5, because 5 × 5 × 5 = 125.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":7},"wordq-cube-root":{"id":"wordq-cube-root","kind":"wordq","src":"dictionary:cube root#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “∛125 = 5, because 5 × 5 × 5 = 125.”","opts":["cube root","mode","Euler’s formula"],"after":"cube root: The number which, used three times in a multiplication, gives the one you started with. Sign: ∛."},"level":7},"word-cubic-centimetre":{"id":"word-cubic-centimetre","kind":"word","src":"dictionary:cubic centimetre#def","title":"cubic centimetre","body":"The volume of a cube 1 cm by 1 cm by 1 cm. Written cm³. For example: A 1 ml spoonful of water fills 1 cm³.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":7},"wordq-cubic-centimetre":{"id":"wordq-cubic-centimetre","kind":"wordq","src":"dictionary:cubic centimetre#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “A 1 ml spoonful of water fills 1 cm³.”","opts":["cubic centimetre","empty set","even chance"],"after":"cubic centimetre: The volume of a cube 1 cm by 1 cm by 1 cm. Written cm³."},"level":7},"word-cuboid":{"id":"word-cuboid","kind":"word","src":"dictionary:cuboid#def","title":"cuboid","body":"A box shape: a solid with six rectangular faces. For example: A box 30 cm × 20 cm × 10 cm.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":7},"wordq-cuboid":{"id":"wordq-cuboid","kind":"wordq","src":"dictionary:cuboid#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “A box 30 cm × 20 cm × 10 cm.”","opts":["cuboid","order of operations","quotient"],"after":"cuboid: A box shape: a solid with six rectangular faces."},"level":7},"word-density":{"id":"word-density","kind":"word","src":"dictionary:density#def","title":"density","body":"How much mass is packed into each unit of volume. For example: 200 g in 100 cm³ is 2 g/cm³.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":7},"wordq-density":{"id":"wordq-density","kind":"wordq","src":"dictionary:density#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “200 g in 100 cm³ is 2 g/cm³.”","opts":["density","diameter","divisible"],"after":"density: How much mass is packed into each unit of volume."},"level":7},"word-direct-proportion":{"id":"word-direct-proportion","kind":"word","src":"dictionary:direct proportion#def","title":"direct proportion","body":"When one amount doubles, the other doubles too; when one halves, so does the other. For example: 3 pens cost £6, so 6 pens cost £12.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":7},"wordq-direct-proportion":{"id":"wordq-direct-proportion","kind":"wordq","src":"dictionary:direct proportion#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “3 pens cost £6, so 6 pens cost £12.”","opts":["direct proportion","times table","mean"],"after":"direct proportion: When one amount doubles, the other doubles too; when one halves, so does the other."},"level":7},"word-distance":{"id":"word-distance","kind":"word","src":"dictionary:distance#def","title":"distance","body":"How far it is from one place to another. For example: 3 hours at 50 km/h covers 150 km.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":7},"wordq-distance":{"id":"wordq-distance","kind":"wordq","src":"dictionary:distance#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “3 hours at 50 km/h covers 150 km.”","opts":["distance","tenth","square root"],"after":"distance: How far it is from one place to another."},"level":7},"word-equally-likely":{"id":"word-equally-likely","kind":"word","src":"dictionary:equally likely#def","title":"equally likely","body":"Having exactly the same chance as each other. For example: Each face of a fair dice: 1/6 each.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":7},"wordq-equally-likely":{"id":"wordq-equally-likely","kind":"wordq","src":"dictionary:equally likely#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “Each face of a fair dice: 1/6 each.”","opts":["equally likely","metric","compound measure"],"after":"equally likely: Having exactly the same chance as each other."},"level":7},"word-factorial":{"id":"word-factorial","kind":"word","src":"dictionary:factorial#def","title":"factorial","body":"A whole number multiplied by every whole number below it, down to 1 — the number of orders that many different things can go in. Sign: !. For example: 5! = 5 × 4 × 3 × 2 × 1 = 120, and 0! = 1.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":7},"wordq-factorial":{"id":"wordq-factorial","kind":"wordq","src":"dictionary:factorial#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “5! = 5 × 4 × 3 × 2 × 1 = 120, and 0! = 1.”","opts":["factorial","diagonal","mental maths"],"after":"factorial: A whole number multiplied by every whole number below it, down to 1 — the number of orders that many different things can go in. Sign: !."},"level":7},"word-outcome":{"id":"word-outcome","kind":"word","src":"dictionary:outcome#def","title":"outcome","body":"One possible result of something like a roll or a spin. For example: A dice has six: 1, 2, 3, 4, 5 and 6.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":7},"wordq-outcome":{"id":"wordq-outcome","kind":"wordq","src":"dictionary:outcome#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “A dice has six: 1, 2, 3, 4, 5 and 6.”","opts":["outcome","linear","substitute"],"after":"outcome: One possible result of something like a roll or a spin."},"level":7},"word-probability":{"id":"word-probability","kind":"word","src":"dictionary:probability#def","title":"probability","body":"How likely something is, as a number from 0 (it cannot happen) to 1 (it must). For example: A fair coin landing heads: 1/2.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":7},"word-rate":{"id":"word-rate","kind":"word","src":"dictionary:rate#def","title":"rate","body":"How much of one thing there is for each one of another. For example: 60 km per hour; £8 per kilogram.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":7},"wordq-rate":{"id":"wordq-rate","kind":"wordq","src":"dictionary:rate#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “60 km per hour; £8 per kilogram.”","opts":["rate","decimal point","Venn diagram"],"after":"rate: How much of one thing there is for each one of another."},"level":7},"word-sample-space":{"id":"word-sample-space","kind":"word","src":"dictionary:sample space#def","title":"sample space","body":"A list or table of every possible outcome. For example: Two coins: HH, HT, TH, TT — 4 outcomes.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":7},"wordq-sample-space":{"id":"wordq-sample-space","kind":"wordq","src":"dictionary:sample space#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “Two coins: HH, HT, TH, TT — 4 outcomes.”","opts":["sample space","empty set","prime factorisation"],"after":"sample space: A list or table of every possible outcome."},"level":7},"word-simple-interest":{"id":"word-simple-interest","kind":"word","src":"dictionary:simple interest#def","title":"simple interest","body":"Extra money on savings or a loan worked out on the starting amount only, so the same amount is added every year. For example: £200 at 5% for 3 years: 3 × £10 = £30.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":7},"wordq-simple-interest":{"id":"wordq-simple-interest","kind":"wordq","src":"dictionary:simple interest#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “£200 at 5% for 3 years: 3 × £10 = £30.”","opts":["simple interest","chance","like terms"],"after":"simple interest: Extra money on savings or a loan worked out on the starting amount only, so the same amount is added every year."},"level":7},"word-speed":{"id":"word-speed","kind":"word","src":"dictionary:speed#def","title":"speed","body":"How far something travels in each unit of time. For example: 120 km in 2 hours is 60 km/h.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":7},"wordq-speed":{"id":"wordq-speed","kind":"wordq","src":"dictionary:speed#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “120 km in 2 hours is 60 km/h.”","opts":["speed","short division","proportion"],"after":"speed: How far something travels in each unit of time."},"level":7},"word-surface-area":{"id":"word-surface-area","kind":"word","src":"dictionary:surface area#def","title":"surface area","body":"The total area of all the faces of a solid. For example: A 1 cm cube: 6 faces × 1 cm² = 6 cm².","route":"#/lib/dictionary","cta":"Open the Dictionary","level":7},"wordq-surface-area":{"id":"wordq-surface-area","kind":"wordq","src":"dictionary:surface area#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “A 1 cm cube: 6 faces × 1 cm² = 6 cm².”","opts":["surface area","negative number","product"],"after":"surface area: The total area of all the faces of a solid."},"level":7},"word-unitary-method":{"id":"word-unitary-method","kind":"word","src":"dictionary:unitary method#def","title":"unitary method","body":"Find the value of one first, then multiply up to the amount you need. For example: 4 cakes cost £8 → 1 costs £2 → 7 cost £14.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":7},"wordq-unitary-method":{"id":"wordq-unitary-method","kind":"wordq","src":"dictionary:unitary method#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “4 cakes cost £8 → 1 costs £2 → 7 cost £14.”","opts":["unitary method","scalene triangle","hundredth"],"after":"unitary method: Find the value of one first, then multiply up to the amount you need."},"level":7},"word-volume":{"id":"word-volume","kind":"word","src":"dictionary:volume#def","title":"volume","body":"How much space a solid takes up, counted in cubes. For example: 4 × 3 × 2 = 24 cm³.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":7},"wordq-volume":{"id":"wordq-volume","kind":"wordq","src":"dictionary:volume#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “4 × 3 × 2 = 24 cm³.”","opts":["volume","power","rounding"],"after":"volume: How much space a solid takes up, counted in cubes."},"level":7},"word-working-backwards":{"id":"word-working-backwards","kind":"word","src":"dictionary:working backwards#def","title":"working backwards","body":"Undoing each step in reverse order to find what you started with. For example: Out 13, rule “× 2 then + 3”: 13 − 3 = 10, 10 ÷ 2 = 5.","route":"#/lib/dictionary","cta":"Open the Dictionary","level":7},"wordq-working-backwards":{"id":"wordq-working-backwards","kind":"wordq","src":"dictionary:working backwards#ex","title":"Which maths word?","route":"#/lib/dictionary","cta":"Open the Dictionary","play":{"q":"Which word is this an example of? “Out 13, rule “× 2 then + 3”: 13 − 3 = 10, 10 ÷ 2 = 5.”","opts":["working backwards","triangle","sum"],"after":"working backwards: Undoing each step in reverse order to find what you started with."},"level":7},"formula-volume-cuboid":{"id":"formula-volume-cuboid","kind":"formula","src":"formula:volume-cuboid","title":"Volume of a cuboid","body":"V = l × w × h. One layer is l × w cubes; there are h layers.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Volume of a cuboid: A box 5 cm by 4 cm by 3 cm.","opts":["60","61","59"],"after":"one layer: 5 × 4 = 20 · V = 20 × 3 = 60 cm³"},"level":7},"formula-why-volume-cuboid-0":{"id":"formula-why-volume-cuboid-0","kind":"formula-why","src":"formula:volume-cuboid#why0","title":"Why V = l × w × h","body":"Fill the bottom of the box with centimetre cubes: that is l × w cubes, one layer.","route":"#/lib/formulas","cta":"Open the Formula Book","level":7},"formula-why-volume-cuboid-1":{"id":"formula-why-volume-cuboid-1","kind":"formula-why","src":"formula:volume-cuboid#why1","title":"Why V = l × w × h","body":"Stack h layers like that and the box is full. So the volume is l × w × h cubic units — the floor’s area times the height.","route":"#/lib/formulas","cta":"Open the Formula Book","level":7},"formula-story-volume-cuboid":{"id":"formula-story-volume-cuboid","kind":"formula-story","src":"formula:volume-cuboid#story","badge":{"id":"story","label":"A story"},"title":"Packing the sugar cubes","body":"Suki is filling a box with sugar cubes. It fits 5 cubes along, 4 across and 3 layers high. — with Nova and Suki.","art":"art/s-shop.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":7},"formula-try-volume-cuboid":{"id":"formula-try-volume-cuboid","kind":"formula-try","src":"formula:volume-cuboid#gen0","title":"Volume of a cuboid — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Volume of a box 5 cm by 10 cm by 6 cm (in cm³) = ?","opts":["300","301","299"],"after":"V = l × w × h"},"level":7},"formula-surface-area-cuboid":{"id":"formula-surface-area-cuboid","kind":"formula","src":"formula:surface-area-cuboid","title":"Surface area of a cuboid","body":"S = 2 × (lw + lh + wh). Unfold the box: three pairs of matching faces.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Surface area of a cuboid: A box 5 cm by 3 cm by 2 cm.","opts":["62","63","61"],"after":"5 × 3 + 5 × 2 + 3 × 2 = 15 + 10 + 6 = 31 · S = 2 × 31 = 62 cm²"},"level":7},"formula-why-surface-area-cuboid-0":{"id":"formula-why-surface-area-cuboid-0","kind":"formula-why","src":"formula:surface-area-cuboid#why0","title":"Why S = 2 × (lw + lh + wh)","body":"A box has six faces, and they come in three matching pairs: top and bottom, front and back, left and right.","route":"#/lib/formulas","cta":"Open the Formula Book","level":7},"formula-why-surface-area-cuboid-1":{"id":"formula-why-surface-area-cuboid-1","kind":"formula-why","src":"formula:surface-area-cuboid#why1","title":"Why S = 2 × (lw + lh + wh)","body":"The pairs have areas l × w, l × h and w × h. Add one of each and double: S = 2 × (lw + lh + wh). Unfold the box into its net and you can see all six at once.","route":"#/lib/formulas","cta":"Open the Formula Book","level":7},"formula-story-surface-area-cuboid":{"id":"formula-story-surface-area-cuboid","kind":"formula-story","src":"formula:surface-area-cuboid#story","badge":{"id":"story","label":"A story"},"title":"Wrapping the present","body":"Dax is wrapping a box 30 cm long, 20 cm wide and 10 cm tall. How much paper covers it exactly? — with Ines and Dax.","art":"art/s-festival.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":7},"formula-try-surface-area-cuboid":{"id":"formula-try-surface-area-cuboid","kind":"formula-try","src":"formula:surface-area-cuboid#gen0","title":"Surface area of a cuboid — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Surface area of a box 9 cm by 5 cm by 7 cm (in cm²) = ?","opts":["286","287","285"],"after":"S = 2 × (lw + lh + wh)"},"level":7},"formula-volume-cube":{"id":"formula-volume-cube","kind":"formula","src":"formula:volume-cube","title":"Volume of a cube","body":"V = s × s × s = s³. s × s in a layer, and s layers: s³, “s cubed”.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Volume of a cube: A cube with 4 cm edges.","opts":["64","65","63"],"after":"4 × 4 = 16 in a layer · V = 16 × 4 = 64 cm³"},"level":7},"formula-why-volume-cube-0":{"id":"formula-why-volume-cube-0","kind":"formula-why","src":"formula:volume-cube#why0","title":"Why V = s × s × s = s³","body":"A cube is a cuboid whose length, width and height are all the same, so l × w × h becomes s × s × s.","route":"#/lib/formulas","cta":"Open the Formula Book","level":7},"formula-why-volume-cube-1":{"id":"formula-why-volume-cube-1","kind":"formula-why","src":"formula:volume-cube#why1","title":"Why V = s × s × s = s³","body":"That is why s³ is called “s cubed”: it counts the little cubes in a big cube of side s. A 3 by 3 by 3 cube holds 9 in each layer and 3 layers: 27.","route":"#/lib/formulas","cta":"Open the Formula Book","level":7},"formula-story-volume-cube":{"id":"formula-story-volume-cube","kind":"formula-story","src":"formula:volume-cube#story","badge":{"id":"story","label":"A story"},"title":"The block tower","body":"Pip builds one big cube out of little wooden blocks, 4 blocks along every edge. — with Mira and Pip.","art":"art/s-room.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":7},"formula-try-volume-cube":{"id":"formula-try-volume-cube","kind":"formula-try","src":"formula:volume-cube#gen0","title":"Volume of a cube — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Volume of a cube with 5 cm edges (in cm³) = ?","opts":["125","126","124"],"after":"V = s × s × s = s³"},"level":7},"formula-volume-prism":{"id":"formula-volume-prism","kind":"formula","src":"formula:volume-prism","title":"Volume of a prism","body":"V = area of end × length. Every slice is the same as the end, so stack the end along the length.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Volume of a prism: A prism whose end is a triangle, base 6 cm and height 4 cm, 10 cm long.","opts":["120","121","119"],"after":"end: 6 × 4 ÷ 2 = 12 cm² · V = 12 × 10 = 120 cm³"},"level":7},"formula-why-volume-prism-0":{"id":"formula-why-volume-prism-0","kind":"formula-why","src":"formula:volume-prism#why0","title":"Why V = area of end × length","body":"A prism is the same shape all the way through, like a loaf of bread: every slice is a copy of the end.","route":"#/lib/formulas","cta":"Open the Formula Book","level":7},"formula-story-volume-prism":{"id":"formula-story-volume-prism","kind":"formula-story","src":"formula:volume-prism#story","badge":{"id":"story","label":"A story"},"title":"The tent","body":"Theo and Suki pitch a tent shaped like a triangular prism. The end is 2 m wide and 1.5 m tall; the tent is 3 m long. — with Suki and Theo.","art":"art/s-forest.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":7},"formula-percent-of-amount":{"id":"formula-percent-of-amount","kind":"formula","src":"formula:percent-of-amount","title":"A percentage of an amount","body":"p% of x = x ÷ 100 × p. 15% is 15 squares out of every 100.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"A percentage of an amount: 15% of 80.","opts":["12","13","11"],"after":"10% = 8, 5% = 4 · 15% = 8 + 4 = 12"},"level":7},"formula-why-percent-of-amount-0":{"id":"formula-why-percent-of-amount-0","kind":"formula-why","src":"formula:percent-of-amount#why0","title":"Why p% of x = x ÷ 100 × p","body":"Per cent means “out of every hundred”. Split the amount into 100 equal parts and each part is 1%: x ÷ 100. Then take p of those parts.","route":"#/lib/formulas","cta":"Open the Formula Book","level":7},"formula-why-percent-of-amount-1":{"id":"formula-why-percent-of-amount-1","kind":"formula-why","src":"formula:percent-of-amount#why1","title":"Why p% of x = x ÷ 100 × p","body":"Often it is quicker to find 10% (divide by 10) and build from it: 30% is three lots of 10%, 5% is half of 10%, 15% is 10% and 5% together.","route":"#/lib/formulas","cta":"Open the Formula Book","level":7},"formula-story-percent-of-amount":{"id":"formula-story-percent-of-amount","kind":"formula-story","src":"formula:percent-of-amount#story","badge":{"id":"story","label":"A story"},"title":"The sale rail","body":"A jacket costs £60. The shop takes 15% off. How much is taken off? — with Ines and Dax.","art":"art/s-shop.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":7},"formula-speed-distance-time":{"id":"formula-speed-distance-time","kind":"formula","src":"formula:speed-distance-time","title":"Speed, distance and time","body":"speed = distance ÷ time. Cover the one you want; the other two tell you what to do.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Speed, distance and time: 240 km in 3 hours.","opts":["80","81","79"],"after":"speed = 240 ÷ 3 · = 80 km/h"},"level":7},"formula-why-speed-distance-time-0":{"id":"formula-why-speed-distance-time-0","kind":"formula-why","src":"formula:speed-distance-time#why0","title":"Why speed = distance ÷ time","body":"Speed says how far you go in each hour (or each second). If a train goes 240 km in 3 hours at a steady speed, each hour carries it the same distance: 240 ÷ 3 = 80 km.","route":"#/lib/formulas","cta":"Open the Formula Book","level":7},"formula-why-speed-distance-time-1":{"id":"formula-why-speed-distance-time-1","kind":"formula-why","src":"formula:speed-distance-time#why1","title":"Why speed = distance ÷ time","body":"The same fact turns round: distance = speed × time, and time = distance ÷ speed. Cover the one you want in the triangle — D on top, S and T below — and the other two tell you what to do.","route":"#/lib/formulas","cta":"Open the Formula Book","level":7},"formula-story-speed-distance-time":{"id":"formula-story-speed-distance-time","kind":"formula-story","src":"formula:speed-distance-time#story","badge":{"id":"story","label":"A story"},"title":"The train to the coast","body":"The train to the coast covers 180 km in 2 hours. Dax wants to know how fast it goes. — with Theo and Dax.","art":"art/s-train.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":7},"formula-try-speed-distance-time":{"id":"formula-try-speed-distance-time","kind":"formula-try","src":"formula:speed-distance-time#gen0","title":"Speed, distance and time — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"A cyclist covers 720 km at 120 km/h. How many hours does it take?","opts":["6","7","5"],"after":"speed = distance ÷ time"},"level":7},"formula-density":{"id":"formula-density","kind":"formula","src":"formula:density","title":"Density","body":"density = mass ÷ volume. Same size, different mass in every cube: different density.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Density: A block of 600 g with a volume of 200 cm³.","opts":["3","4","2"],"after":"density = 600 ÷ 200 · = 3 g/cm³"},"level":7},"formula-why-density-0":{"id":"formula-why-density-0","kind":"formula-why","src":"formula:density#why0","title":"Why density = mass ÷ volume","body":"Density is a compound measure, like speed: it says how many grams are packed into each cubic centimetre. Share the mass equally over the volume: mass ÷ volume.","route":"#/lib/formulas","cta":"Open the Formula Book","level":7},"formula-why-density-1":{"id":"formula-why-density-1","kind":"formula-why","src":"formula:density#why1","title":"Why density = mass ÷ volume","body":"A brick and a sponge of the same size have the same volume but very different masses, so very different densities. Like speed, it turns round: mass = density × volume.","route":"#/lib/formulas","cta":"Open the Formula Book","level":7},"formula-story-density":{"id":"formula-story-density","kind":"formula-story","src":"formula:density#story","badge":{"id":"story","label":"A story"},"title":"The mystery stone","body":"Theo finds a smooth stone on the beach. It has a mass of 270 g. Dropped into a measuring jug, it pushes the water up by 100 cm³. — with Theo and Mira.","art":"art/s-beach.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":7},"formula-try-density":{"id":"formula-try-density","kind":"formula-try","src":"formula:density#gen0","title":"Density — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"A block has a mass of 90 g and a volume of 10 cm³. Its density (in g/cm³)?","opts":["9","10","8"],"after":"density = mass ÷ volume"},"level":7},"formula-probability":{"id":"formula-probability","kind":"formula","src":"formula:probability","title":"Probability","body":"P = ways it can happen ÷ all the ways. Count what you want, over everything that could happen.","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"Probability: A bag of 3 red and 5 blue counters. The chance of red?","opts":["3/8","8/3","4/8"],"after":"all the ways: 3 + 5 = 8 · P(red) = 3/8"},"level":7},"formula-why-probability-0":{"id":"formula-why-probability-0","kind":"formula-why","src":"formula:probability#why0","title":"Why P = ways it can happen ÷ all the ways","body":"When every outcome is equally likely, count them all: that is the bottom of the fraction. Count the ones you want: that is the top.","route":"#/lib/formulas","cta":"Open the Formula Book","level":7},"formula-why-probability-1":{"id":"formula-why-probability-1","kind":"formula-why","src":"formula:probability#why1","title":"Why P = ways it can happen ÷ all the ways","body":"A bag with 3 red and 5 blue counters has 8 counters, so the chance of red is 3/8. The chances of everything that could happen always add up to 1 — here 3/8 + 5/8 = 1.","route":"#/lib/formulas","cta":"Open the Formula Book","level":7},"formula-story-probability":{"id":"formula-story-probability","kind":"formula-story","src":"formula:probability#story","badge":{"id":"story","label":"A story"},"title":"The raffle","body":"The carnival raffle sold 50 tickets. Pip bought 5 of them. What is his chance of winning the prize? — with Ines and Pip.","art":"art/s-carnival.webp","route":"#/lib/formulas","cta":"Open the Formula Book","level":7},"formula-try-probability":{"id":"formula-try-probability","kind":"formula-try","src":"formula:probability#gen0","title":"Probability — your turn","route":"#/lib/formulas","cta":"Open the Formula Book","play":{"q":"A bag has 6 red and 8 blue counters. You pick one without looking. The chance it is red, as a fraction?","opts":["6/14","14/6","7/14"],"after":"P = ways it can happen ÷ all the ways"},"level":7}};
